test('DOM-91 EACH STORY HAS ITS OWN CANON SWITCH: on in one story in Settings, off in the next one opened, on again back in the first — the switch names the story it is for (M399)', async () => {
  const before = errors.length;
  const a = await db.stories.create({ title: 'Bleach, captain Oda' });
  const b = await db.stories.create({ title: 'A tale of my own' });
  const open = async (id) => { env.window.__cozy.setActiveStoryId(id); await env.window.__cozy.chat.renderThread({ structural: true }); await tick(100); };
  try {
    await open(a.id);
    await openSettings();
    let sw = await until(() => q('#canon-on'), 'the switch', 10000);
    await until(() => /Bleach, captain Oda/.test(sw.closest('label').textContent), 'it names the story it is for', 5000);
    eq(sw.checked, false, 'off until switched on');
    sw.checked = true; sw.dispatchEvent(new env.window.Event('change', { bubbles: true }));
    await until(async () => (await db.settings.get('canonOn:' + a.id)) === true, 'on for this story', 5000);
    await closeSettings();
    await open(b.id);
    await openSettings();
    sw = await until(() => q('#canon-on'), 'the switch', 10000);
    await until(() => /A tale of my own/.test(sw.closest('label').textContent), 'now it is the other story’s', 5000);
    eq(sw.checked, false, 'the other story is off');
    eq(await db.settings.get('canonOn:' + b.id), undefined, 'and nothing was written for it');
    await closeSettings();
    await open(a.id);
    await openSettings();
    sw = await until(() => q('#canon-on'), 'the switch', 10000);
    await until(() => sw.checked === true, 'back in the first story, on as it was left', 5000);
    await closeSettings();
  } finally {
    await db.settings.delete('canonOn:' + a.id);
    await closeSettings().catch(() => {});
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-92 EVERY PERSON HAS A BANNER: here (even when the scene names her "Lieutenant Rukia Kuchiki" or "Kuchiki Rukia"), elsewhere, or plainly "whereabouts not yet written" — never a blank (M404)', async () => {
  const before = errors.length;
  const { saveState, emptyState } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const st = await db.stories.create({ title: 'Banners' });
  let ledger = applyMutations({ ...emptyState(), page: 1 }, [{ type: 'mc.set', name: 'Jovan Oda' }, { type: 'place.set', name: '10th Division HQ — training courtyard' },
    { type: 'presence.enter', name: 'Jovan Oda' }, { type: 'presence.enter', name: 'Lieutenant Rukia Kuchiki' }, { type: 'presence.enter', name: 'Kuchiki Byakuya' },
    { type: 'offscreen.set', name: 'Renji Abarai', location: '6th Division barracks', activity: 'drilling', stance: 'busy' }]).state;
  ledger.characters = { 'Rukia Kuchiki': { core: 'His lieutenant.', state: 'x', threads: [] }, 'Byakuya Kuchiki': { core: 'Captain of the 6th.', state: 'x', threads: [] }, 'Renji Abarai': { core: 'Lieutenant of the 6th.', state: 'x', threads: [] }, 'Iba Tetsuzaemon': { core: 'Lieutenant of the 7th.', state: '', threads: [] } };
  await saveState(st.id, { ...ledger, readTo: 0, tidiedGen: 999, healedGen: 999 });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  try {
    click(q('#btn-ledger'));
    await until(() => !q('#drawer').hidden, 'the drawer');
    await tick(300); await env.ctx.drawer.renderAllRooms(); await tick(300);
    const room = qa('#drawer-panels .ledger-panel').find((x) => x.querySelector('h3') && x.querySelector('h3').textContent.trim() === 'The people');
    await until(() => room && /Carried by/.test(room.textContent), 'the pages drawn', 10000);
    const head = (who) => [...room.querySelectorAll('li.people-row > strong')].map((s) => s.textContent).find((t) => t.startsWith(who)) || '';
    eq(head('Rukia Kuchiki'), 'Rukia Kuchiki — here', 'here, though the scene names her "Lieutenant Rukia Kuchiki"');
    eq(head('Byakuya Kuchiki'), 'Byakuya Kuchiki — here', 'here, though the scene names him family name first');
    eq(head('Renji Abarai'), 'Renji Abarai — elsewhere', 'elsewhere');
    eq(head('Iba Tetsuzaemon'), 'Iba Tetsuzaemon — whereabouts not yet written', 'and never a blank');
    click(q('#btn-ledger'));
  } finally {
    if (!q('#drawer').hidden) click(q('#btn-ledger'));
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-94 HIS WORDS ARE NEVER LOST ON THE WAY OUT: the frame, the note and the story\u2019s brief typed and left by closing Settings — without “Keep it” — are kept, and drawn back when it opens; a plain open and close keeps nothing (M426)', async () => {
  const before = errors.length;
  const sid = await storyId();
  const was = { frame: await db.settings.get('frameText'), note: await db.settings.get('noteText'), brief: ((await db.stories.get(sid)) || {}).brief };
  const writes = [];
  const set0 = db.settings.set; const upd0 = db.stories.update;
  db.settings.set = async (...a) => { writes.push('settings:' + a[0]); return set0.apply(db.settings, a); };
  db.stories.update = async (...a) => { writes.push('story:' + Object.keys(a[1] || {}).join(',')); return upd0.apply(db.stories, a); };
  try {
    await openSettings(); await tick(300);
    await closeSettings(); await tick(400);
    eq(writes.filter((w) => /frameText|noteText|frameOn|noteOn|brief|castNotes|frameOverride|noteOverride/.test(w)).length, 0, 'a plain open and close keeps nothing: ' + writes.join(' '));
    /* another hand changes the brief while Settings stands open (a housekeeper card, a name the ripple carries): the box,
     * drawn before it and never typed in, never writes its stale words back over it */
    await openSettings(); await tick(300);
    await upd0.call(db.stories, sid, { brief: 'Written by another hand while Settings was open.' });
    await closeSettings(); await tick(600);
    eq(((await db.stories.get(sid)) || {}).brief, 'Written by another hand while Settings was open.', 'a box he never typed in keeps nothing over another hand\u2019s change');
    await openSettings(); await tick(300);
    const typeInto = (id, words) => { const box = q('#' + id); box.value = words; box.dispatchEvent(new env.window.Event('input', { bubbles: true })); };
    typeInto('frame-global', 'You are Lothar, and you tell it by the fire.');
    typeInto('note-global', 'Keep the duel fast.');
    typeInto('brief-story', 'Oda is the new captain of the 13th Division.');
    /* M428: a live redraw while he is typing (a sync from his other browser, a shelf change) never writes over his draft */
    env.ctx.onStoriesChanged(); await tick(600);
    eq(q('#frame-global').value, 'You are Lothar, and you tell it by the fire.', 'a redraw while he types leaves his frame draft on screen');
    eq(q('#brief-story').value, 'Oda is the new captain of the 13th Division.', 'and his brief draft');
    await closeSettings();
    await until(async () => (await db.settings.get('frameText')) === 'You are Lothar, and you tell it by the fire.', 'the frame kept on the way out', 8000);
    await until(async () => (await db.settings.get('noteText')) === 'Keep the duel fast.', 'the note kept', 8000);
    await until(async () => ((await db.stories.get(sid)) || {}).brief === 'Oda is the new captain of the 13th Division.', 'the brief kept', 8000);
    await openSettings(); await tick(400);
    await until(() => q('#frame-global').value === 'You are Lothar, and you tell it by the fire.', 'and drawn back when Settings opens: ' + q('#frame-global').value.slice(0, 80), 10000); /* M639: filled after it shows, as above */
    eq(q('#brief-story').value, 'Oda is the new captain of the 13th Division.', 'the brief too');
  } finally {
    db.settings.set = set0; db.stories.update = upd0;
    await closeSettings();
    if (was.frame === undefined) await db.settings.delete('frameText'); else await db.settings.set('frameText', was.frame);
    if (was.note === undefined) await db.settings.delete('noteText'); else await db.settings.set('noteText', was.note);
    await db.stories.update(sid, { brief: was.brief || '' });
    await settled();
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-95 THE LEDGER IS NEVER REDRAWN UNDER HIS FINGERS: typing in a field of the drawer while the workers write, the field stays — the same field, his words in it, the focus kept — and the room catches up the moment he leaves it (M428)', async () => {
  const before = errors.length;
  const sid = await storyId();
  { if (!q('#drawer').hidden) { click(q('#btn-drawer-close')); await until(() => q('#drawer').hidden, 'the drawer put away'); } click(q('#btn-ledger')); await until(() => !q('#drawer').hidden, 'drawer'); } /* opened fresh for THIS story */
  await tick(400);
  /* the world's room holds the elsewhere form — a field to type in whatever room the ledger last had open */
  const chip = await until(() => q('#drawer .drawer-rooms [data-room="world"]'), 'the world room', 8000);
  click(chip); await tick(500); await env.ctx.drawer.renderAllRooms(); await tick(400);
  const field = await until(() => q('#drawer input[aria-label="Where they’ve gone"]'), 'a field in the open ledger', 8000);
  field.focus();
  field.value = 'half a word he is typi';
  field.dispatchEvent(new env.window.Event('input', { bubbles: true }));
  const { loadState, saveState, notify } = await import('../../js/engine/state.js');
  /* the workers write, twice, well past the redraw's wait */
  for (let k = 0; k < 2; k += 1) { const st = await loadState(sid); await saveState(sid, { ...st, turn: (Number(st.turn) || 0) + 1 }); notify(sid); await tick(1900); }
  assert(field.isConnected, 'the same field still stands — not redrawn away under his fingers');
  eq(field.value, 'half a word he is typi', 'his words are in it');
  eq(document.activeElement, field, 'and the focus is his still (the keyboard stays open)');
  field.blur();
  await until(() => !field.isConnected, 'the room catches up once he leaves the field', 6000);
  click(q('#btn-ledger')); await until(() => q('#drawer').hidden, 'drawer closed', 5000).catch(() => {});
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-96 A PAGE HE IS RE-INKING IS NEVER REDRAWN AWAY: he opens the editor on the newest page while the workers still read it — the world agent\u2019s write-back lands under the page and the whole thread is asked to redraw — and his editor, his words and the focus stay; the page is drawn with his words once he keeps them (M429)', async () => {
  const before = errors.length;
  const sid = await storyId();
  const prior = house.state.workerAnswer;
  let release; const held = new Promise((r) => { release = r; });
  house.state.workerAnswer = (body, sys) => (/world beyond the page/i.test(sys) ? held.then(() => JSON.stringify({ mutations: [], brief: { pressure: [], ripe: [], twb: null, voices: [{ speaker: 'Kim', channel: 'text', content: 'Where are you?' }] } })) : prior(body, sys));
  try {
    type(q('#composer-input'), 'I wait by the window.');
    submit(q('#composer'));
    await until(() => !q('.msg-pending') && !q('.msg.streaming') && !env.ctx.chat.isBusy(), 'the page landed', 30000);
    const last = assistantPages().slice(-1)[0];
    const id = last.dataset.id;
    click(q('.msg-act[data-act="edit"]', last));
    const box = await until(() => q('textarea.edit-box', last), 'the editor', 10000);
    box.value = box.value + ' He is re-inking this line';
    box.dispatchEvent(new env.window.Event('input', { bubbles: true }));
    release(); /* the world agent answers: its voices are written under the page (a re-ink of this very page) */
    await until(async () => { const m = (await db.messages.list(sid)).find((x) => x.id === id); return m && Array.isArray(m.voices) && m.voices.length; }, 'the write-back landed', 20000);
    /* and a whole redraw of the thread comes while he types (a housekeeper card's re-inks, a live sync, a shelf change) */
    env.ctx.chat.renderThread({ structural: true });
    env.ctx.onStoriesChanged();
    await tick(800);
    assert(box.isConnected, 'his editor still stands — not redrawn away under him');
    assert(/He is re-inking this line$/.test(box.value), 'his words are in it');
    eq(document.activeElement, box, 'and the focus is his');
    const keep = [...box.parentElement.querySelectorAll('button')].find((b) => /Keep the new words/.test(b.textContent));
    click(keep);
    await until(async () => { const m = (await db.messages.list(sid)).find((x) => x.id === id); return m && /He is re-inking this line/.test(m.text); }, 'his words kept', 15000);
    await until(() => !q('textarea.edit-box'), 'the editor closes', 10000);
    await settled();
    const again = qa('.msg-assistant').find((n) => n.dataset.id === id);
    assert(again && /He is re-inking this line/.test(again.textContent), 'and the page is drawn with his kept words (the voices are the drawer\u2019s, M97)');
  } finally {
    release();
    house.state.workerAnswer = prior;
    await settled();
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

