test('DOM-98 A CHANGE NEVER LANDS UNDER AN ANSWER STILL COMING: while the housekeeper is answering, Undo waits for it (the answer saves the talk as it found it, and would write the take-back over) — and afterwards takes back exactly once (M442)', async () => {
  const before = errors.length;
  const sid = await storyId();
  await db.stories.update(sid, { brief: 'Rias is his older sister.' });
  const prior = house.state.workerAnswer;
  let release; const held = new Promise((r) => { release = r; });
  let asked = 0;
  house.state.workerAnswer = (body, sys) => {
    if (!/housekeeper of a cozy tavern/i.test(sys)) return prior(body, sys);
    asked += 1;
    if (asked === 1) return 'Done.\n<brief>[{"field":"brief","find":"older sister","replace":"younger sister","reason":"asked"}]</brief>';
    return held.then(() => 'Nothing more to change.');
  };
  try {
    if (q('#hk-sheet').hidden) { click(q('#btn-housekeeper')); await until(() => !q('#hk-sheet').hidden, 'the housekeeper'); }
    await until(() => !q('#hk-send').disabled, 'the housekeeper free', 10000);
    type(q('#hk-input'), 'make her the younger sister'); submit(q('#hk-form'));
    const apply = await until(() => qa('#hk-cards button').find((b) => /^Apply$/i.test(b.textContent.trim())), 'the card', 10000).catch(() => null);
    if (apply) click(apply);
    await until(async () => /younger sister/.test((await db.stories.get(sid)).brief), 'the brief changed', 10000);
    await until(() => !q('#hk-send').disabled, 'free again', 10000);
    type(q('#hk-input'), 'anything else?'); submit(q('#hk-form'));
    await until(() => q('#hk-send').disabled, 'the housekeeper answering', 10000);
    click(q('#hk-undo')); await tick(600);
    assert(/younger sister/.test((await db.stories.get(sid)).brief), 'while the answer is coming, Undo waits — the brief stands');
    release();
    await until(() => !q('#hk-send').disabled, 'the answer landed', 15000);
    click(q('#hk-undo'));
    await until(async () => /older sister/.test((await db.stories.get(sid)).brief), 'now Undo takes it back', 10000);
    click(q('#hk-undo')); await tick(800);
    assert(/older sister/.test((await db.stories.get(sid)).brief), 'and only once — nothing is taken back twice');
  } finally {
    release();
    house.state.workerAnswer = prior;
    await until(() => !q('#hk-send').disabled, 'free', 10000).catch(() => {});
    if (!q('#hk-sheet').hidden) { const close = q('#btn-hk-close') || q('#btn-housekeeper'); click(close); }
    await tick(300);
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-99 THE HOUSEKEEPER SCREEN KEEPS WHAT IS HIS: the director\u2019s three doors survive a redraw and a reopen; a hand edit on a card survives the story settling behind it; an answer that lands after he moved to another tale lands its cards there (M443)', async () => {
  const before = errors.length;
  const sid = await storyId();
  await db.stories.update(sid, { brief: 'Rias is his older sister. The house is on Elm Street.' });
  const prior = house.state.workerAnswer;
  let release; const held = new Promise((r) => { release = r; });
  let mode = 'doors';
  house.state.workerAnswer = (body, sys) => {
    if (!/housekeeper of a cozy tavern/i.test(sys)) return prior(body, sys);
    if (mode === 'card') return 'One change.\n<brief>[{"field":"brief","find":"older sister","replace":"younger sister","reason":"asked"}]</brief>';
    return held.then(() => 'Moved it.\n<brief>[{"field":"brief","find":"Elm Street","replace":"Oak Street","reason":"asked"}]</brief>');
  };
  const reopen = async () => { if (!q('#hk-sheet').hidden) { click(q('#btn-hk-close')); await tick(400); } click(q('#btn-housekeeper')); await until(() => !q('#hk-sheet').hidden, 'the housekeeper'); await tick(300); };
  try {
    await reopen();
    await until(() => !q('#hk-send').disabled, 'free', 10000);
    /* 1. the three doors, kept */
    const priorStory = house.state.storyAnswer;
    house.state.storyAnswer = 'DOOR-ONE a letter arrives. DOOR-TWO a fire. DOOR-THREE a guest.'; /* the director's tools ride the storyteller's wire in the fake house */
    try {
      click(q('#hk-more')); click(q('#hk-more-menu [data-act="dir-ideas"]'));
      await until(() => /DOOR-TWO/.test(q('#hk-thread').textContent), 'the three doors drawn', 10000);
    } finally { house.state.storyAnswer = priorStory; }
    env.ctx.housekeeper.onStoriesChanged(); await tick(500);
    assert(/DOOR-TWO/.test(q('#hk-thread').textContent), 'a redraw keeps them');
    await reopen();
    assert(/DOOR-TWO/.test(q('#hk-thread').textContent), 'and a reopen');
    /* 2. a hand edit survives the story settling behind it */
    await db.settings.set('hkAutoApply', false);
    mode = 'card';
    type(q('#hk-input'), 'make her the younger sister'); submit(q('#hk-form'));
    const edit = await until(() => qa('#hk-cards button').find((b) => /Edit by hand/i.test(b.textContent)), 'the card\u2019s Edit by hand', 10000);
    await until(() => !q('#hk-send').disabled, 'the answer settled', 10000);
    click(edit);
    const area = await until(() => q('#hk-cards textarea'), 'the hand edit box', 5000);
    area.value = 'the youngest sister of three';
    env.ctx.housekeeper.onStoriesChanged(); await tick(600);
    assert(area.isConnected && area.value === 'the youngest sister of three', 'the story settling does not redraw his hand edit away');
    click([...q('#hk-cards').querySelectorAll('button')].find((b) => /Keep & apply/.test(b.textContent)));
    await until(async () => /youngest sister of three/.test((await db.stories.get(sid)).brief), 'his hand-tuned words applied', 10000);
    await db.settings.delete('hkAutoApply');
    /* 3. an answer that lands after he moved to another tale lands its cards in the tale that asked */
    mode = 'held';
    await until(() => !q('#hk-send').disabled, 'free again', 10000);
    type(q('#hk-input'), 'move the house to Oak Street'); submit(q('#hk-form'));
    await until(() => q('#hk-send').disabled, 'asking', 10000);
    click(q('#btn-hk-close')); await tick(300);
    click(q('#btn-new-story'));
    await until(() => !q('#new-story-form').hidden, 'the new-story form');
    type(q('#new-story-title'), 'Elsewhere for a moment');
    submit(q('#new-story-form'));
    await until(async () => (await storyId()) !== sid, 'another tale open', 10000);
    click(q('#btn-housekeeper')); await until(() => !q('#hk-sheet').hidden, 'the housekeeper, open on the other tale'); await tick(400);
    release();
    await until(async () => /Oak Street/.test((await db.stories.get(sid)).brief), 'the card landed in the tale that asked', 15000);
  } finally {
    release();
    house.state.workerAnswer = prior;
    await db.settings.delete('hkAutoApply');
    if (!q('#hk-sheet').hidden) { click(q('#btn-hk-close')); await tick(300); }
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-93 "READ AGAIN" PUTS THE GROUND WHERE THE PAGE SAYS AND LETS GO OF THE NOW OF A PLACE LEFT — Kyōraku stands where the page and his now agree (M588), Rukia’s courtyard now stays, the page is untouched, and no card says "the next page" (M409)', async () => {
  const before = errors.length;
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  const { saveState, loadState, emptyState } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const PAGE = '[10th Division HQ — Monday, June 1, 2026 | 10:00 | clear | shihakushō | on the sand]\n\nJovan and Zaraki circle each other; Rukia watches from the rail.';
  const st = await db.stories.create({ title: 'The ground of the page' });
  await db.stories.update(st.id, { keeper: false });
  await db.messages.append(st.id, { role: 'user', text: 'I step onto the sand.' });
  const page = await db.messages.append(st.id, { role: 'assistant', text: PAGE });
  /* the ground as the pages had it, the nows written where they were, then an old audit's wrong move of the ground */
  let ledger = applyMutations({ ...emptyState(), page: 1 }, [{ type: 'mc.set', name: 'Jovan Oda' }, { type: 'place.set', name: '10th Division HQ' },
    ...['Jovan Oda', 'Shunsui Kyōraku', 'Rukia Kuchiki', 'Kenpachi Zaraki'].map((n) => ({ type: 'presence.enter', name: n })),
    { type: 'people.set', name: 'Rukia Kuchiki', field: 'core', text: 'His lieutenant.' }, { type: 'people.set', name: 'Rukia Kuchiki', field: 'state', text: 'at the 10th Division HQ rail, arms folded' },
    { type: 'people.set', name: 'Kenpachi Zaraki', field: 'core', text: 'Captain of the 11th.' },
    { type: 'place.set', name: '1st Division HQ — outside the assembly hall' },
    { type: 'people.set', name: 'Shunsui Kyōraku', field: 'core', text: 'Captain-Commander.' }, { type: 'people.set', name: 'Shunsui Kyōraku', field: 'state', text: 'inside the assembly hall at 1st Division HQ, among the assembled captains' }]).state;
  await saveState(st.id, { ...ledger, readTo: 1, tidiedGen: 999, healedGen: 999 });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  try {
    const row = await until(() => q(`.msg[data-id="${page.id}"] .msg-act[data-act="read again"]`), 'read again under the page', 10000);
    click(row);
    await tick(500);
    await until(() => queuedCount(st.id) === 0 && !workIsRunning(st.id), 'the readers', 40000);
    const after = await loadState(st.id);
    assert(/10th Division HQ/.test(after.place.name), 'the ground is where the page says: ' + after.place.name);
    /* M588: the page shows Jovan, Zaraki and Rukia on the sand — not Kyōraku. Read again, he is no longer counted on the sand
     * (whoever the page does not show stays at the old ground): he stands at the 1st Division, which is where his own now
     * puts him — so either his assembly-hall now is let go (he is here) or he is seated there and it stands, never both */
    const kyoHere = after.present.some((p) => /Kyōraku/.test(p.name));
    const kyoNow = String(after.characters['Shunsui Kyōraku'].state || '');
    const kyoSeat = after.offscreen['Shunsui Kyōraku'];
    assert(kyoHere ? !/assembly hall/i.test(kyoNow) : Boolean(kyoSeat && /1st Division/.test(kyoSeat.location || '')), 'Kyōraku is where the page and his now agree: here ' + kyoHere + ', now ' + kyoNow + ', seat ' + JSON.stringify(kyoSeat));
    assert(/10th Division HQ rail/.test(String(after.characters['Rukia Kuchiki'].state || '')), 'Rukia’s courtyard now stays');
    eq((await db.messages.list(st.id)).find((m) => m.id === page.id).text, PAGE, 'the page is untouched');
    click(q('#btn-ledger'));
    await until(() => !q('#drawer').hidden, 'the drawer');
    await tick(300); await env.ctx.drawer.renderAllRooms(); await tick(300);
    const room = qa('#drawer-panels .ledger-panel').find((x) => x.querySelector('h3') && x.querySelector('h3').textContent.trim() === 'The people');
    assert(room && !/the next page writes/.test(room.textContent), 'no card promises "the next page"');
    click(q('#btn-ledger'));
  } finally {
    if (!q('#drawer').hidden) click(q('#btn-ledger'));
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

