test('DOM-107 A PAGE READ OUT OF TURN NEVER MOVES THE MOMENT, PLAYED THROUGH THE REAL READERS: an old assembly-hall page no read reached is read late — its ground and its people stay out of today’s duel; what it taught lasts (M453)', async () => {
  const before = errors.length;
  const { saveState, loadState, emptyState } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const HALL = '1st Division HQ — outside the assembly hall';
  const YARD = '10th Division HQ — training courtyard';
  const st = await db.stories.create({ title: 'The duel, read late' });
  await db.stories.update(st.id, { keeper: false });
  await db.messages.append(st.id, { role: 'user', text: 'I wait for the announcement.' });
  await db.messages.append(st.id, { role: 'assistant', text: '[' + HALL + ' — Sunday, Hanami 5, 1001 AG | 08:00 | spring sun | haori | by the doors]\n\nThe captains assembled; Kyōraku named Oda captain of the 13th. OLDPAGE' });
  const ledger = applyMutations({ ...emptyState(), page: -1 }, [{ type: 'mc.set', name: 'Jovan Oda' }, { type: 'place.set', name: YARD },
    ...['Jovan Oda', 'Kenpachi Zaraki'].map((n) => ({ type: 'presence.enter', name: n }))]).state;
  ledger.characters = { 'Kenpachi Zaraki': { core: 'Captain of the 11th.', threads: [] }, 'Shunsui Kyōraku': { core: 'Captain-Commander.', threads: [] } };
  await saveState(st.id, { ...ledger, readTo: -1, tidiedGen: 999, healedGen: 999 }); /* the assembly page was never read */
  house.state.storyAnswer = 'Zaraki widened his stance on the torn sand of the courtyard, grinning. NEWPAGE';
  house.state.workerAnswer = (body, sys) => {
    if (/keep the ledger/i.test(sys)) {
      const page = newPageOf(String((body.messages || []).slice(-1)[0].content || ''));
      if (/OLDPAGE/.test(page)) return JSON.stringify({ mutations: [{ type: 'place.set', name: HALL }, { type: 'presence.enter', name: 'Shunsui Kyōraku' }, { type: 'knowledge.add', name: 'Kenpachi Zaraki', fact: 'the assembly named Oda captain of the 13th' }, { type: 'mode.snapshot', flags: ['group'] }] });
      return JSON.stringify({ mutations: [{ type: 'mode.snapshot', flags: ['combat'] }] });
    }
    if (/world beyond the page/i.test(sys)) return JSON.stringify({ mutations: [], brief: { pressure: [], ripe: [], twb: null, voices: [] } });
    return walkDefaultWorker(body, sys);
  };
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  try {
    type(q('#composer-input'), 'I draw on Zaraki.');
    submit(q('#composer'));
    await until(async () => (await db.messages.list(st.id)).filter((m) => m.role === 'assistant').length === 2 && !env.ctx.chat.isBusy(), 'the page', 15000);
    await until(async () => queuedCount(st.id) === 0 && !workIsRunning(st.id) && (await loadState(st.id)).worldBrief, 'the readers', 40000);
    await settled();
    const after = await loadState(st.id);
    eq(after.place.name, YARD, 'the ground stays the courtyard');
    assert(!after.present.some((p) => /Kyōraku/.test(p.name)), 'the assembly’s Kyōraku is not written into the duel: ' + after.present.map((p) => p.name).join(', '));
    const k = after.knowledge && (after.knowledge['Kenpachi Zaraki'] || []);
    assert(Array.isArray(k) && k.some((x) => /named Oda captain/.test(x.fact)), 'what the old page taught lasts');
  } finally {
    house.state.storyAnswer = null;
    house.state.workerAnswer = walkDefaultWorker;
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-108 THE PAGES THE LEDGER MISSED ARE READ IN ONE GO, WITH THE COUNT ON SHOW: five missed pages, read one after another while the house is idle — the banner counts them and ends at 100%, and the light is not left yellow (M454)', async () => {
  const before = errors.length;
  const { saveState, loadState, emptyState, readMark } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const st = await db.stories.create({ title: 'The backlog' });
  await db.stories.update(st.id, { keeper: false, createdAt: Date.now() - 3600000 });
  for (let i = 0; i < 6; i += 1) {
    await db.messages.append(st.id, { role: 'user', text: 'I go on. (' + i + ')' });
    await db.messages.append(st.id, { role: 'assistant', text: 'Rukia filed the rosters. MISSED-' + i });
  }
  const ledger = applyMutations({ ...emptyState(), page: 0 }, [{ type: 'mc.set', name: 'Jovan Oda' }, { type: 'place.set', name: "13th Division Barracks — Captain's Office" },
    ...['Jovan Oda', 'Rukia Kuchiki'].map((n) => ({ type: 'presence.enter', name: n }))]).state;
  await saveState(st.id, { ...ledger, readTo: 0, tidiedGen: 999, healedGen: 999 }); /* pages 2–6 never read */
  let reads = 0;
  const readLog = [];
  house.state.workerAnswer = (body, sys) => {
    if (/keep the ledger/i.test(sys)) {
      const page = newPageOf(String((body.messages || []).slice(-1)[0].content || ''));
      const n = (page.match(/MISSED-(\d)/) || [])[1];
      if (n) { reads += 1; readLog.push(n); }
      /* the newest page's answer carries the mood board; the older pages' do not — they are not asked again for it */
      return JSON.stringify({ mutations: n ? [{ type: 'knowledge.add', name: 'Rukia Kuchiki', fact: 'the roster for week ' + n + ' is filed' }, ...(n === '5' ? [{ type: 'mode.snapshot', flags: [] }] : [])] : [] });
    }
    return walkDefaultWorker(body, sys);
  };
  try {
    env.window.__cozy.setActiveStoryId(st.id);
    await env.window.__cozy.chat.renderThread({ structural: true }); /* the light looks, sees the gap, and sends the reader */
    await until(async () => readMark(await loadState(st.id)) === 5 && queuedCount(st.id) === 0 && !workIsRunning(st.id), 'every missed page read', 30000);
    await tick(200);
    eq(reads, 5, 'all five read, one after another, each once: ' + readLog.join(', '));
    eq(q('#work-banner-what').textContent, 'The ledger has read every page', 'the banner says so');
    eq(q('#work-banner-count').textContent, 'done', 'at its end');
    eq(q('#work-banner-fill').style.width, '100%', '100%');
    const k = (await loadState(st.id)).knowledge['Rukia Kuchiki'] || [];
    eq(k.length, 5, 'what each page taught landed');
  } finally {
    house.state.workerAnswer = walkDefaultWorker;
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-109 THE CLOCK FOLLOWS HIS NEWEST PAGE ON HIS OWN CALENDAR, THROUGH THE REAL APP: a reader that guesses a page behind on another calendar (and adds time on top) is outranked by the header — and a ledger left a page behind is put right when the story opens (M455)', async () => {
  const before = errors.length;
  const { saveState, loadState, emptyState, saveVersionStates } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const { renderClock } = await import('../../js/engine/clock.js');
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const YARD = 'Tenth Division Courtyard';
  const st = await db.stories.create({ title: 'Hanami' });
  await db.stories.update(st.id, { keeper: false });
  const lagging = applyMutations({ ...emptyState(), page: -1 }, [{ type: 'mc.set', name: 'Jovan Oda' }, { type: 'place.set', name: YARD },
    { type: 'clock.set', year: 1001, month: 3, day: 5, hour: 9, minute: 19 }, ...['Jovan Oda', 'Kenpachi Zaraki'].map((n) => ({ type: 'presence.enter', name: n }))]).state;
  await saveState(st.id, { ...lagging, readTo: -1, tidiedGen: 999, healedGen: 999 });
  const PAGE = '[' + YARD + ' — Sunday, Hanami 5, 1001 AG | 09:20 | blinding spring sun, drifting sand | black shihakushō, no haori | mid-sand]\n\nZaraki rolled his shoulders on the drifting sand, grinning.';
  house.state.storyAnswer = PAGE;
  house.state.workerAnswer = (body, sys) => {
    if (/keep the ledger/i.test(sys)) return JSON.stringify({ mutations: [{ type: 'clock.set', year: 1001, month: 3, day: 5, hour: 9, minute: 19 }, { type: 'clock.advance', minutes: 5 }, { type: 'mode.snapshot', flags: ['combat'] }] });
    if (/world beyond the page/i.test(sys)) return JSON.stringify({ mutations: [], brief: { pressure: [], ripe: [], twb: null, voices: [] } });
    return walkDefaultWorker(body, sys);
  };
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  try {
    type(q('#composer-input'), 'I draw.');
    submit(q('#composer'));
    await until(async () => (await db.messages.list(st.id)).some((m) => m.role === 'assistant') && !env.ctx.chat.isBusy(), 'the page', 15000);
    await until(async () => queuedCount(st.id) === 0 && !workIsRunning(st.id) && (await loadState(st.id)).worldBrief, 'the readers', 40000);
    await settled();
    eq(renderClock((await loadState(st.id)).clock), 'Sunday, Hanami 5, 1001 AG — 09:20', 'the page’s own hour and day — the reader’s guess and its extra five minutes outranked');
    /* a ledger a page behind (as his stood), and the story opened: nothing pressed */
    const page = (await db.messages.list(st.id)).find((m) => m.role === 'assistant');
    await saveState(st.id, { ...(await loadState(st.id)), clock: lagging.clock });
    await saveVersionStates(st.id, { [page.id + ':0']: await loadState(st.id) });
    await db.stories.update(st.id, { createdAt: Date.now() - 3600000 });
    await env.ctx.chat.openStory(st.id);
    await until(async () => renderClock((await loadState(st.id)).clock) === 'Sunday, Hanami 5, 1001 AG — 09:20', 'the clock to be put right on open', 10000);
  } finally {
    house.state.storyAnswer = null;
    house.state.workerAnswer = walkDefaultWorker;
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-110 USAGE AND COST, IN SETTINGS: what the calls took today, over 7 and 30 days, and per day, week and month — each connection and model on its own row, priced from its own prices; the price boxes stand in the connection editor (M457)', async () => {
  const before = errors.length;
  const { dayKey, addToDay, USAGE_PREFIX } = await import('../../js/engine/usage.js');
  const conn = await db.connections.add({ name: 'Claude', label: 'Claude', type: 'anthropic', baseUrl: 'https://api.anthropic.com', apiKey: 'k', model: 'claude-opus-5-5', priceIn: 3, priceOut: 15 });
  const connId = conn && conn.id ? conn.id : (await db.connections.list()).find((c) => c.label === 'Claude').id;
  /* the books of every other day go first: a walk that runs across midnight wrote its earlier calls into yesterday's book,
   * and the averages (a month's spend over the days since the first one used) halved — the one day seeded is the whole story */
  for (const k of ((await db.settings.keys()) || []).filter((k) => String(k).startsWith(USAGE_PREFIX))) await db.settings.delete(k);
  await db.settings.set(USAGE_PREFIX + dayKey(Date.now()), addToDay({}, { connId, connName: 'Claude', model: 'claude-opus-5-5', inTok: 2000000, outTok: 100000 }));
  await openSettings();
  click(q('[data-room="storyteller"]'));
  const box = await until(() => { const b = q('#usage-box'); return b && b.querySelector('.usage-total') ? b : null; }, 'the usage room', 10000);
  const total = box.querySelector('.usage-total').textContent;
  assert(/2M/.test(total) && /100k/.test(total) && /\$7\.50/.test(total), 'today: 2M in, 100k out, $7.50 — ' + total);
  const avg = [...box.querySelectorAll('.usage-avg-row')].map((r) => r.textContent);
  eq(avg.length, 3, 'per day, per week, per month');
  assert(/\$7\.50/.test(avg[0]) && /\$52\.50/.test(avg[1]) && /\$225/.test(avg[2]), avg.join(' | '));
  click([...box.querySelectorAll('.usage-periods button')].find((b) => b.dataset.period === 'month'));
  assert(/Claude · claude-opus-5-5/.test(box.querySelector('.usage-table').textContent), 'its row, by connection and model');
  assert(q('#conn-price-in') && q('#conn-price-out'), 'the price boxes stand in the connection editor');
  /* M510-25: his busiest day, per model — and a month of days like it; and the cache's own price box */
  const busiest = [...box.querySelectorAll('.usage-busiest-table tr')].find((r) => r.dataset.model === 'claude-opus-5-5');
  assert(busiest, 'the busiest-day row for Claude · claude-opus-5-5 stands');
  const cells = [...busiest.querySelectorAll('td')].map((c) => c.textContent);
  assert(/2M in · 100k out · \$7\.50/.test(cells[2]) && /60M in · 3M out · \$225/.test(cells[3]), 'that day, and thirty of it a month: ' + cells.join(' | '));
  assert(/Your busiest day, per model/.test(box.textContent), 'the section says what it is');
  assert(q('#conn-price-cached'), 'the cached-input price box stands in the connection editor');
  /* M510-30: the busiest day folds until he opens it, and stays as he left it; the fallback for every worker stands in The workers */
  const fold = box.querySelector('details.usage-busiest');
  assert(fold && !fold.open && /Your busiest day, per model/.test(fold.querySelector('summary').textContent), 'folded, its name showing');
  fold.open = true; fold.dispatchEvent(new env.window.Event('toggle'));
  await until(async () => (await db.settings.get('usageBusiestOpen')) === true, 'opened, and remembered');
  const fb = q('#worker-fallback');
  assert(fb && fb.options.length >= 2 && fb.options[0].value === '' && /No fallback/.test(fb.options[0].textContent), 'the fallback picker: none, or any connection');
  fb.value = fb.options[1].value; fb.dispatchEvent(new env.window.Event('change', { bubbles: true }));
  await until(async () => (await db.settings.get('workerFallbackId')) === fb.options[1].value, 'the fallback saved');
  await db.settings.set('workerFallbackId', null); await db.settings.set('usageBusiestOpen', false);
  await closeSettings();
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-111 THE WIKI LIBRARY, ONE TAP: in a story’s own canon room the library is offered as chips — a tap puts it in the story’s wiki box and keeps it; "Add to library" saves the box’s wiki for every story (M457)', async () => {
  const before = errors.length;
  const { addToLibrary, canonLibrary, canonMeta } = await import('../../js/canon/bridge.js');
  const st = await db.stories.create({ title: 'Library tale' });
  await db.messages.append(st.id, { role: 'user', text: 'I arrive.' });
  await db.messages.append(st.id, { role: 'assistant', text: 'Rukia Kuchiki bowed.' });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await db.settings.set('canonOn:' + st.id, true);
  await addToLibrary('bleach');
  const openRoom = async (title) => {
    { if (!q('#drawer').hidden) { click(q('#btn-drawer-close')); await until(() => q('#drawer').hidden, 'the drawer put away'); } click(q('#btn-ledger')); await until(() => !q('#drawer').hidden, 'the drawer'); } /* opened fresh for THIS story: an open drawer shows the story it was opened for */
    await tick(300); await env.ctx.drawer.renderAllRooms(); await tick(300);
    const sec = qa('#drawer-panels .ledger-panel').find((x) => x.querySelector('h3') && x.querySelector('h3').textContent.trim() === title);
    assert(sec, 'the room “' + title + '” is in the ledger');
    return sec;
  };
  const room = await openRoom('What canon says');
  const chips = await until(() => room.querySelector('#canon-library-chips'), 'the library chips', 10000);
  const chip = [...chips.querySelectorAll('button.lib-chip')].find((b) => b.textContent === 'bleach');
  assert(chip, 'the library is offered in the story’s room');
  click(chip);
  await until(async () => String((await canonMeta(st.id)).canon_grounding_wiki || '').includes('bleach'), 'the story to keep the wiki it was handed', 15000);
  /* "Add to library" in another story's room — the first room goes on checking the wiki it was handed (its own business,
   * however long the wiki takes to answer) */
  const st2 = await db.stories.create({ title: 'Library tale, two' });
  await db.messages.append(st2.id, { role: 'user', text: 'I arrive.' });
  await db.messages.append(st2.id, { role: 'assistant', text: 'Issei grinned.' });
  await db.settings.set('canonOn:' + st2.id, true);
  if (!q('#drawer').hidden) { click(q('#btn-ledger')); await until(() => q('#drawer').hidden, 'the drawer closed'); }
  env.window.__cozy.setActiveStoryId(st2.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await openRoom('What canon says');
  const inRoom = (sel) => { const r = qa('#drawer-panels .ledger-panel').find((x) => x.querySelector('h3') && x.querySelector('h3').textContent.trim() === 'What canon says'); return r ? r.querySelector(sel) : null; };
  const box = await until(() => inRoom('#canon-story-wiki'), 'the box', 20000);
  box.value = 'highschooldxd';
  click(await until(() => inRoom('#canon-add-library'), 'Add to library', 20000));
  await until(async () => (await canonLibrary()).includes('highschooldxd'), 'the library to hold it', 10000);
  if (!q('#drawer').hidden) { click(q('#btn-ledger')); await until(() => q('#drawer').hidden, 'the drawer closed'); }
  await db.settings.set('canonOn:' + st.id, false);
  await db.settings.set('canonOn:' + st2.id, false);
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-112 HER JAPANESE STANDS AND THE MARKS ARE MADE WHOLE, THROUGH THE REAL APP: he asks her to moan in Japanese; the page keeps "Yamete" (the second reader’s "not established to speak Japanese" is let go, the mender never asked), and the storyteller’s *"…"* is kept as "…" (M458)', async () => {
  const before = errors.length;
  const { saveState, emptyState } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const st = await db.stories.create({ title: 'Yamete' });
  await db.stories.update(st.id, { keeper: false });
  const ledger = applyMutations({ ...emptyState(), page: -1 }, [{ type: 'mc.set', name: 'Jovan Oda' }, { type: 'place.set', name: 'Her quarters' }, ...['Jovan Oda', 'Rukia Kuchiki'].map((n) => ({ type: 'presence.enter', name: n }))]).state;
  await saveState(st.id, { ...ledger, readTo: -1, tidiedGen: 999, healedGen: 999 });
  house.state.storyAnswer = '[Her quarters | 23:10]\n\nRukia arched against him, breath breaking. *"Yamete… yamete—"* The word dissolved into a gasp.';
  let mended = 0;
  house.state.workerAnswer = (body, sys) => {
    if (/continuity reader/i.test(sys)) return JSON.stringify({ findings: [{ severity: 'warn', words: 'Rukia moans in Japanese ("yamete"); she is not established as speaking Japanese', fix: 'Stop… stop—' }] });
    if (/You mend a story/i.test(sys)) { mended += 1; return '{"pages":[]}'; }
    if (/keep the ledger/i.test(sys)) return JSON.stringify({ mutations: [{ type: 'mode.snapshot', flags: ['intimate'] }], here: ['Jovan Oda', 'Rukia Kuchiki'] });
    if (/world beyond the page/i.test(sys)) return JSON.stringify({ mutations: [], brief: { pressure: [], ripe: [], twb: null, voices: [] } });
    return walkDefaultWorker(body, sys);
  };
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  try {
    type(q('#composer-input'), 'I whisper to her: moan for me in Japanese.');
    submit(q('#composer'));
    await until(async () => (await db.messages.list(st.id)).some((m) => m.role === 'assistant') && !env.ctx.chat.isBusy(), 'the page', 15000);
    await until(async () => queuedCount(st.id) === 0 && !workIsRunning(st.id), 'the readers', 40000);
    await settled();
    const page = (await db.messages.list(st.id)).find((m) => m.role === 'assistant');
    const text = page.text || (page.swipes && page.swipes[page.swipeIdx || 0]) || '';
    assert(/"Yamete… yamete—"/.test(text), 'her Japanese stands, its marks whole: ' + text);
    assert(!/\*"/.test(text) && !/Stop… stop/.test(text), 'no asterisks around her speech, and never "stop, stop"');
    eq(mended, 0, 'the mender was never asked');
  } finally {
    house.state.storyAnswer = null;
    house.state.workerAnswer = walkDefaultWorker;
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-113 THE WIKI LIBRARY IS A SWITCH FOR THIS STORY, IN SETTINGS: a tap on "bleach" uses it here, a tap on "jjk" makes it a crossover (the story looks in both), a second tap on "bleach" stops using it — and the line above says where it looks (M463)', async () => {
  const before = errors.length;
  const { addToLibrary, canonMeta } = await import('../../js/canon/bridge.js');
  const st = await db.stories.create({ title: 'Crossover' });
  await db.messages.append(st.id, { role: 'user', text: 'I arrive.' });
  await db.messages.append(st.id, { role: 'assistant', text: 'Rukia bowed; Gojo grinned.' });
  await db.settings.set('canonOn:' + st.id, true);
  await addToLibrary('bleach', 'jjk');
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  const binding = async () => String((await canonMeta(st.id)).canon_grounding_wiki || '');
  try {
    await openSettings();
    click([...qa('#view-settings .nav-chip')].find((c) => /The readers/.test(c.textContent)));
    click(await until(() => q('#canon-lib-use-bleach'), 'bleach, tappable', 15000));
    await until(async () => (await binding()) === 'bleach', 'the story to look in bleach', 40000);
    click(await until(() => { const b = q('#canon-lib-use-jjk'); return b && !b.disabled ? b : null; }, 'jjk, tappable', 15000));
    await until(async () => /bleach/.test(await binding()) && /jjk/.test(await binding()), 'a crossover — both', 40000);
    await until(() => /This story looks in: bleach \+ jjk \(a crossover\)/.test((q('#canon-library') || {}).textContent || ''), 'the line to say so', 15000);
    click(await until(() => { const b = q('#canon-lib-use-bleach'); return b && !b.disabled && /✓/.test(b.textContent) ? b : null; }, 'bleach, marked in use', 15000));
    await until(async () => (await binding()) === 'jjk', 'bleach let go, jjk kept', 40000);
    await closeSettings();
  } finally {
    await db.settings.set('canonOn:' + st.id, false);
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-114 AUTOMATIC IS A SWITCH YOU CAN SEE AND TAP: with bleach and jjk chosen (a crossover), a tap on "Automatic" lets the choice go and the story finds its own — the wiki it finds is never shown as his pick; the last chosen wiki tapped off is Automatic again (M464)', async () => {
  const before = errors.length;
  const { addToLibrary, canonMeta } = await import('../../js/canon/bridge.js');
  const st = await db.stories.create({ title: 'Automatic' });
  await db.messages.append(st.id, { role: 'user', text: 'I arrive.' });
  await db.messages.append(st.id, { role: 'assistant', text: 'Rukia bowed.' });
  await db.settings.set('canonOn:' + st.id, true);
  await addToLibrary('bleach', 'jjk');
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  const meta = async () => (await canonMeta(st.id)) || {};
  const manual = async () => Boolean(((await meta()).canon_grounding_wiki_ok || {}).manual);
  try {
    await openSettings();
    click([...qa('#view-settings .nav-chip')].find((c) => /The readers/.test(c.textContent)));
    const auto0 = await until(() => q('#canon-lib-auto'), 'Automatic, drawn', 15000);
    assert(/✓/.test(auto0.textContent), 'a story nobody chose for is Automatic');
    click(await until(() => q('#canon-lib-use-bleach'), 'bleach', 15000));
    await until(async () => (await manual()) && (await meta()).canon_grounding_wiki === 'bleach', 'his pick', 40000);
    click(await until(() => { const b = q('#canon-lib-use-jjk'); return b && !b.disabled ? b : null; }, 'jjk', 15000));
    await until(async () => /bleach/.test((await meta()).canon_grounding_wiki) && /jjk/.test((await meta()).canon_grounding_wiki), 'the crossover', 40000);
    const autoOff = await until(() => { const b = q('#canon-lib-auto'); return b && !/✓/.test(b.textContent) ? b : null; }, 'Automatic unchecked while he chooses', 15000);
    click(autoOff);
    await until(async () => !(await manual()), 'his choice let go — the story finds its own', 40000);
    await until(() => { const b = q('#canon-lib-auto'); return b && /✓/.test(b.textContent); }, 'Automatic checked again', 15000);
    assert(!/✓/.test((q('#canon-lib-use-bleach') || {}).textContent || '') && !/✓/.test((q('#canon-lib-use-jjk') || {}).textContent || ''), 'what it found by itself is never shown as his pick');
    click(await until(() => { const b = q('#canon-lib-use-jjk'); return b && !b.disabled ? b : null; }, 'jjk again', 15000));
    await until(async () => (await manual()) && (await meta()).canon_grounding_wiki === 'jjk', 'a pick from Automatic starts a new choice', 40000);
    click(await until(() => { const b = q('#canon-lib-use-jjk'); return b && !b.disabled && /✓/.test(b.textContent) ? b : null; }, 'jjk checked', 15000));
    await until(async () => !(await manual()), 'the last one off is Automatic again', 40000);
    await closeSettings();
  } finally {
    await db.settings.set('canonOn:' + st.id, false);
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});


/* ---------- M466: the ledger folds, the page mark, the shelves' order and rest, his own-voice words ---------- */

test('DOM-115 THE LEDGER FOLDS: a room opens with only what it is for unfolded; a tap on a name opens or folds it, the count sits beside it, and the fold is remembered across a redraw', async () => {
  const before = errors.length;
  const st = await db.stories.create({ title: 'Folded tale' });
  await db.messages.append(st.id, { role: 'user', text: 'I arrive.' });
  await db.messages.append(st.id, { role: 'assistant', text: 'Rukia Kuchiki bowed. Byakuya Kuchiki nodded.' });
  const { saveState, emptyState } = await import('../../js/engine/state.js');
  const s0 = emptyState(); s0.sheet = { actors: {}, playerName: 'Jovan' };
  s0.present = [{ name: 'Jovan' }, { name: 'Rukia Kuchiki' }, { name: 'Byakuya Kuchiki' }];
  s0.characters = { 'Rukia Kuchiki': { core: 'a lieutenant', state: 'bowing', updatedAtTurn: 1, firstSeenTurn: 1 } };
  await saveState(st.id, s0);
  await db.settings.delete('ledgerFolds').catch(() => {});
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  { if (!q('#drawer').hidden) { click(q('#btn-drawer-close')); await until(() => q('#drawer').hidden, 'the drawer put away'); } click(q('#btn-ledger')); await until(() => !q('#drawer').hidden, 'the drawer'); } /* opened fresh for THIS story: an open drawer shows the story it was opened for */
  await tick(300);
  const chip = qa('#drawer-panels .nav-chip').find((c) => c.dataset.room === 'scene'); click(chip); await tick(400);
  const sec = (title) => qa('#drawer-panels .ledger-panel').find((x) => x.querySelector('h3') && x.querySelector('h3').textContent.trim() === title);
  const here = sec('Who’s here'); const mood = sec('The mood of the scene'); const ruling = sec('The house has ruled');
  assert(here && mood && ruling, 'the scene room is drawn');
  assert(!here.classList.contains('folded'), 'Who’s here stands open — it is what the room is for');
  assert(mood.classList.contains('folded') && ruling.classList.contains('folded'), 'the mood and the ruling wait folded');
  eq(here.querySelector('h3').getAttribute('aria-expanded'), 'true'); eq(mood.querySelector('h3').getAttribute('aria-expanded'), 'false');
  eq(here.querySelector('h3').textContent.trim(), 'Who’s here', 'the name is still exactly the name (no button text inside it)');
  await until(() => (here.querySelector(':scope > .fold-count') || {}).textContent === '3', 'the count beside Who’s here says three rows', 5000);
  click(mood.querySelector('h3')); await tick(50);
  assert(!mood.classList.contains('folded'), 'a tap on the name opens it');
  click(here.querySelector('h3')); await tick(50);
  assert(here.classList.contains('folded'), 'and folds it');
  await until(async () => { const f = await db.settings.get('ledgerFolds'); return f && f['the-mood'] === false && f['whos-here'] === true; }, 'both remembered', 5000);
  /* a redraw keeps his folds */
  click(q('#btn-drawer-close')); await tick(300);
  click(q('#btn-ledger')); await until(() => !q('#drawer').hidden, 'the drawer again'); await tick(400);
  assert(sec('The mood of the scene') && !sec('The mood of the scene').classList.contains('folded'), 'the mood is still open after a redraw');
  assert(sec('Who’s here') && sec('Who’s here').classList.contains('folded'), 'Who’s here is still folded');
  /* the keyboard: Enter on the name */
  const h = sec('Who’s here').querySelector('h3');
  h.dispatchEvent(new env.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true, cancelable: true })); await tick(50);
  assert(!sec('Who’s here').classList.contains('folded'), 'Enter on the name opens it');
  click(q('#btn-drawer-close')); await tick(300);
  await db.settings.delete('ledgerFolds').catch(() => {});
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-116 THE PAGE MARK: every storyteller page is numbered over the whole tale — the number does not move when fewer turns are on screen — and the mark is in the room', async () => {
  const before = errors.length;
  const st = await db.stories.create({ title: 'Numbered tale' });
  for (let i = 1; i <= 8; i += 1) {
    await db.messages.append(st.id, { role: 'user', text: 'Turn ' + i + '.' });
    await db.messages.append(st.id, { role: 'assistant', text: 'Page ' + i + ' of the tale.' });
  }
  env.window.__cozy.setActiveStoryId(st.id);
  await db.settings.set('turnsShown', 5);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await until(() => qa('#thread .msg[data-page]').length === 5, 'five storyteller pages on screen', 5000);
  eq(qa('#thread .msg[data-page]').map((n) => n.dataset.page).join(','), '4,5,6,7,8', 'the last five carry their true numbers');
  eq(q('#thread').dataset.pages, '8', 'the thread knows the tale has eight pages');
  const mark = q('#page-mark');
  assert(mark && mark.parentElement === q('#thread').parentElement, 'the mark rides beside the thread');
  eq(mark.getAttribute('role'), 'slider');
  assert(Number.isFinite(env.ctx.pageMark.pageUnderEye()), 'the mark can name a page (jsdom lays nothing out — the number itself is measured in a real browser, tests/paint_coats.py)');
  await db.settings.set('turnsShown', 30);
  await env.window.__cozy.chat.renderThread({ structural: true });
  eq(qa('#thread .msg[data-page]').map((n) => n.dataset.page).join(','), '1,2,3,4,5,6,7,8', 'all eight, numbered from one');
  /* M483: the page that LANDS (in place of its pending node) is numbered too — it was the one page the mark never saw */
  await until(() => !env.ctx.chat.isBusy() && !q('.msg-pending'), 'the house free', 20000);
  type(q('#composer-input'), 'I go on.'); submit(q('#composer'));
  await until(() => qa('#thread .msg-assistant').length === 9 && !q('.msg-pending'), 'the ninth page landed', 30000);
  await until(() => !env.ctx.chat.isBusy() && qa('#thread .msg-assistant').pop().dataset.id, 'the landed node in place of the pending one', 20000);
  const nodes = qa('#thread .msg-assistant');
  eq(nodes[nodes.length - 1].dataset.page, '9', 'the landed page carries its number');
  eq(q('#thread').dataset.pages, '9', 'and the tale knows it has nine');
  await until(() => !env.ctx.chat.isBusy(), 'idle', 20000);
  /* and a page redrawn in place after a worker re-inked it keeps its number */
  const last = (await db.messages.list(st.id)).filter((m) => m.role === 'assistant').pop();
  await env.window.__cozy.chat.rerenderMessage(st.id, last.id);
  eq(qa('#thread .msg-assistant').pop().dataset.page, '9', 'a re-ink keeps the number');
  await db.settings.delete('turnsShown').catch(() => {});
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-117 THE SHELVES SORTED AND PUT TO REST: by name, by last played, newest first — remembered; a shelf put to rest keeps its tales in a corner at the foot, is not offered for a move, and wakes', async () => {
  const before = errors.length;
  const rows = await db.projects.list();
  const alpha = await db.projects.create({ name: 'Alpha shelf' });
  const zeta = await db.projects.create({ name: 'Zeta shelf' });
  const a = await db.stories.create({ title: 'Bravo tale' }); await db.stories.update(a.id, { projectId: alpha.id });
  const z = await db.stories.create({ title: 'Able tale' }); await db.stories.update(z.id, { projectId: zeta.id });
  const zz = await db.stories.create({ title: 'Charlie tale' }); await db.stories.update(zz.id, { projectId: zeta.id });
  await env.ctx.chat.refreshStories(true);
  const shelfNames = () => qa('#story-list > .shelf:not(.resting-shelf) .shelf-head .shelf-name').map((n) => n.textContent);
  const sort = q('#shelf-sort'); assert(sort, 'the sort is in the panel');
  sort.value = 'name'; sort.dispatchEvent(new env.window.Event('change', { bubbles: true })); await tick(100);
  const byName = shelfNames();
  assert(byName.indexOf('Alpha shelf') < byName.indexOf('Zeta shelf'), 'by name: Alpha before Zeta — ' + byName.join(', '));
  const zetaTales = () => { const s = qa('#story-list > .shelf').find((x) => (x.querySelector('.shelf-name') || {}).textContent === 'Zeta shelf'); return s ? qa('.story-item', s).map((li) => li.querySelector('.story-title, .story-name, strong, span') && li.textContent) : []; };
  const t = zetaTales(); assert(t.length === 2 && /Able tale/.test(t[0]) && /Charlie tale/.test(t[1]), 'the tales on a shelf by name too: ' + t.map((x) => x.slice(0, 20)).join(' | '));
  eq(await db.settings.get('shelfSort'), 'name', 'remembered');
  sort.value = 'played'; sort.dispatchEvent(new env.window.Event('change', { bubbles: true })); await tick(100);
  /* touch Zeta's tale: Zeta was played last */
  await db.stories.update(z.id, { preview: 'played just now' }); await env.ctx.chat.refreshStories(true); await tick(50);
  const played = shelfNames();
  assert(played.indexOf('Zeta shelf') < played.indexOf('Alpha shelf'), 'last played first: Zeta leads — ' + played.join(', '));
  /* rest Zeta */
  const zetaHead = qa('#story-list > .shelf').find((x) => (x.querySelector('.shelf-name') || {}).textContent === 'Zeta shelf');
  const rest = qa('button', zetaHead).find((b) => /Put to rest the shelf/.test(b.getAttribute('aria-label') || ''));
  assert(rest, 'the shelf has a rest button');
  click(rest);
  await until(async () => (await db.projects.list()).find((p) => p.id === zeta.id).archived === true, 'the shelf rests', 5000);
  await tick(100);
  assert(!shelfNames().includes('Zeta shelf'), 'a resting shelf leaves the standing shelves');
  const corner = q('#story-list .resting-shelves');
  assert(corner && /resting shel/.test(corner.textContent), 'and waits in the corner at the foot');
  assert(qa('.story-item', corner).length === 2, 'with its two tales still on it');
  eq((await db.stories.get(z.id)).projectId, zeta.id, 'the tales stay on the shelf');
  /* not offered for a move */
  const row = qa('#story-list .story-item').find((li) => /Bravo tale/.test(li.textContent));
  row.dispatchEvent(new env.window.MouseEvent('contextmenu', { bubbles: true, cancelable: true, clientX: 10, clientY: 10 })); await tick(60);
  const offered = qa('#story-menu button[data-act="move-shelf"]').map((b) => b.textContent);
  assert(offered.includes('Alpha shelf') || true, 'the menu drew');
  assert(!offered.includes('Zeta shelf'), 'a resting shelf is not offered: ' + offered.join(', '));
  document.body.dispatchEvent(new env.window.MouseEvent('click', { bubbles: true })); await tick(40);
  /* wake it */
  click(qa('button', corner).find((b) => /Wake the shelf/.test(b.getAttribute('aria-label') || '')) || corner.querySelector('.shelf-head'));
  await until(async () => (await db.projects.list()).find((p) => p.id === zeta.id).archived === false, 'the shelf wakes', 5000).catch(() => {});
  if ((await db.projects.list()).find((p) => p.id === zeta.id).archived !== false) {
    /* the corner was folded: open it, then wake */
    click(corner.querySelector('.shelf-head')); await tick(80);
    const wake = qa('#story-list button').find((b) => /Wake the shelf “Zeta shelf”/.test(b.getAttribute('aria-label') || ''));
    assert(wake, 'the wake button is in the corner');
    click(wake);
    await until(async () => (await db.projects.list()).find((p) => p.id === zeta.id).archived === false, 'the shelf wakes', 5000);
  }
  await tick(100);
  assert(shelfNames().includes('Zeta shelf'), 'it is back among the shelves');
  for (const id of [a.id, z.id, zz.id]) await db.stories.remove(id);
  await db.projects.remove(alpha.id); await db.projects.remove(zeta.id);
  await db.settings.delete('shelfSort').catch(() => {});
  await env.ctx.chat.refreshStories(true);
  eq((await db.projects.list()).length, rows.length, 'the shelves are as they were');
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-118 HIS OWN-VOICE WORDS, THROUGH THE REAL APP: added in Settings, kept, sent at the chosen landmark as the storyteller’s own message; switched off, not sent; let go, gone', async () => {
  const before = errors.length;
  await db.settings.delete('ownWords').catch(() => {});
  await openSettings();
  click([...qa('#view-settings .nav-chip')].find((c) => /This story/.test(c.textContent))); await tick(200);
  const add = q('#btn-own-words-add'); assert(add, 'the section is in Settings');
  click(add); await tick(100);
  const card = await until(() => q('#own-words-list .own-words-card'), 'a card', 5000);
  type(card.querySelector('.own-words-name'), 'Stay Iron Man');
  card.querySelector('textarea').value = 'OWN-MARK: {{teller}} here — still me.';
  const place = card.querySelectorAll('select')[1]; place.value = 'before-your-message'; place.dispatchEvent(new env.window.Event('change', { bubbles: true }));
  click([...card.querySelectorAll('button')].find((b) => b.textContent === 'Keep it'));
  await until(async () => { const w = await db.settings.get('ownWords'); return w && w[0] && w[0].name === 'Stay Iron Man' && /OWN-MARK/.test(w[0].text) && w[0].place === 'before-your-message'; }, 'kept as one settings row', 5000);
  await closeSettings();
  await db.settings.set('tellerName', 'Iron Man');
  /* a turn: the entry rides right before his message, as an assistant message */
  const st = await db.stories.create({ title: 'Own words tale' });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await until(() => !env.ctx.chat.isBusy() && !q('.msg-pending'), 'the house free', 20000);
  const from = house.state.calls.length;
  type(q('#composer-input'), 'I look at the door.'); submit(q('#composer'));
  await until(() => house.state.calls.slice(from).some((c) => !c.isWorker), 'the storyteller asked — note: ' + (q('#composer-note') ? q('#composer-note').textContent : '') + ' errors: ' + errorsSince(before).join(' | '), 15000);
  const call = house.state.calls.slice(from).find((c) => !c.isWorker);
  const msgs = call.body.messages || [];
  const at = msgs.findIndex((m) => /OWN-MARK: Iron Man here — still me\./.test(String(m.content)));
  assert(at !== -1, 'his words are in the request, the name filled in: ' + msgs.map((m) => m.role).join(' '));
  eq(msgs[at].role, 'assistant', 'as the storyteller’s own message');
  const his = msgs.findIndex((m) => m.role === 'user' && /I look at the door\./.test(String(m.content)));
  /* M510-38: on a tale's first turn too, the entry stands where he put it — right before his message */
  eq(at, his - 1, 'right before his message, on the first turn too');
  await until(() => !env.ctx.chat.isBusy() && !q('.msg-pending'), 'the page landed', 20000);
  /* the next turn: the entry stands where he put it, right before his message */
  const fromMid = house.state.calls.length;
  type(q('#composer-input'), 'I step closer.'); submit(q('#composer'));
  await until(() => house.state.calls.slice(fromMid).some((c) => !c.isWorker), 'the storyteller asked again');
  const mid = house.state.calls.slice(fromMid).find((c) => !c.isWorker).body.messages || [];
  const atMid = mid.findIndex((m) => /OWN-MARK: Iron Man here — still me\./.test(String(m.content)));
  const hisMid = mid.findIndex((m) => m.role === 'user' && /I step closer\./.test(String(m.content)));
  eq(atMid, hisMid - 1, 'right before his message');
  await until(() => !env.ctx.chat.isBusy() && !q('.msg-pending'), 'the second page landed', 20000);
  /* switched off: gone from the next request */
  const w = await db.settings.get('ownWords'); await db.settings.set('ownWords', [{ ...w[0], on: false }]);
  const from2 = house.state.calls.length;
  type(q('#composer-input'), 'I wait.'); submit(q('#composer'));
  await until(() => house.state.calls.slice(from2).some((c) => !c.isWorker), 'the storyteller asked again', 15000);
  const call2 = house.state.calls.slice(from2).find((c) => !c.isWorker);
  assert(!(call2.body.messages || []).some((m) => /OWN-MARK/.test(String(m.content))), 'off: not sent');
  await until(() => !env.ctx.chat.isBusy() && !q('.msg-pending'), 'the page landed', 20000);
  /* let go, with the question asked */
  await openSettings();
  click([...qa('#view-settings .nav-chip')].find((c) => /This story/.test(c.textContent))); await tick(200);
  const card2 = await until(() => q('#own-words-list .own-words-card'), 'the card again', 5000);
  const asked = []; const realConfirm = env.window.confirm; env.window.confirm = (m) => { asked.push(m); return true; };
  try { click([...card2.querySelectorAll('button')].find((b) => /Let these words go/.test(b.textContent))); await tick(100); } finally { env.window.confirm = realConfirm; }
  assert(asked.length === 1 && /Stay Iron Man/.test(asked[0]), 'letting words go asks first, naming them');
  await until(async () => ((await db.settings.get('ownWords')) || []).length === 0, 'gone', 5000);
  await closeSettings();
  await db.settings.delete('tellerName').catch(() => {});
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});


