test('DOM-125 STOP MID-PAGE, THEN TRY AGAIN: the half page is kept and marked stopped; Try again asks the same turn with his own words (never "Go on.", never twice), one page stands for the turn, the mark is gone, the house is idle', async () => {
  const before = errors.length;
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  const H = '[The kitchen — Monday, March 3, 2025 | 09:05 | clear | apron | by the stove]\n\n';
  const prior = house.state.storyAnswer;
  const st = await db.stories.create({ title: 'stop mid-page' });
  await db.messages.append(st.id, { role: 'user', text: 'We sit in the kitchen.' });
  await db.messages.append(st.id, { role: 'assistant', text: H + 'The kettle sang and nobody moved.' });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await until(() => !env.ctx.chat.isBusy() && !q('.msg-pending'), 'the house free', 20000);
  try {
    house.state.thinkHang = 'prose';
    type(q('#composer-input'), 'I open the door.'); submit(q('#composer'));
    await until(() => /The kitchen/.test((q('.msg.pending') || {}).textContent || ''), 'the page streaming (its header on screen; an unfinished line is held back from the live view)', 10000);
    await tick(200);
    click(q('#btn-stop'));
    await until(() => !env.ctx.chat.isBusy(), 'stopped', 10000);
    house.state.thinkHang = null;
    let list = await db.messages.list(st.id);
    const half = list.filter((m) => m.role === 'assistant' && !m.hidden).pop();
    assert(/and the door/.test(half.text) && half.stopped === true, 'the half page is kept, marked stopped: ' + JSON.stringify({ text: half.text.slice(-40), stopped: half.stopped }));
    eq(list.filter((m) => m.role === 'user' && m.text === 'I open the door.').length, 1, 'his message once');
    /* Try again */
    house.state.storyAnswer = () => H + 'She turns the handle, and the door opens onto rain.';
    const from = house.state.calls.length;
    await tellerIdle('free after the stop');
    eq(tryAgain(), 'his', '“try again” under his own message (M675: the footer’s button is gone)');
    await until(async () => { const a = (await db.messages.list(st.id)).filter((m) => m.role === 'assistant' && !m.hidden).pop(); return a && /opens onto rain/.test(a.swipes && a.swipes.length ? a.swipes[Number.isFinite(a.swipeIdx) ? a.swipeIdx : a.swipes.length - 1].text : a.text) && !env.ctx.chat.isBusy(); }, 'the new page landed', 30000);
    await until(() => queuedCount(st.id) === 0 && !workIsRunning(st.id), 'the readers settled', 30000);
    const told = house.state.calls.slice(from).filter((c) => !c.isWorker && Array.isArray(c.body.messages));
    eq(told.length, 1, 'one request to the storyteller');
    const lastUser = told[0].body.messages.filter((m) => m.role === 'user').pop();
    eq(String(lastUser.content), 'I open the door.', 'asked with his own words, not "Go on."');
    list = await db.messages.list(st.id);
    eq(list.filter((m) => m.role === 'user' && m.text === 'I open the door.').length, 1, 'his message still once');
    const visible = list.filter((m) => !m.hidden).map((m) => m.role).join(' ');
    eq(visible, 'user assistant user assistant', 'one page stands for the turn: ' + visible);
    const now = list.filter((m) => m.role === 'assistant' && !m.hidden).pop();
    assert(!now.stopped || (Array.isArray(now.swipes) && now.swipes[Number.isFinite(now.swipeIdx) ? now.swipeIdx : now.swipes.length - 1].stopped !== true), 'the page on screen is not marked stopped');
    assert(qa('#thread .msg-assistant').pop().textContent.includes('opens onto rain'), 'the thread shows the new page');
  } finally {
    house.state.thinkHang = null;
    house.state.storyAnswer = prior;
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});


test('DOM-126 TRY AGAIN WHILE THE READERS ARE STILL READING: a reader held on the replaced page answers after the new page lands — its words are refused (the page it read was let go); the new page’s reading stands; nothing is doubled', async () => {
  const before = errors.length;
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  const { loadState } = await import('../../js/engine/state.js');
  const H = '[The hall — Monday, March 3, 2025 | 09:05 | clear | coat | by the door]\n\n';
  const priorStory = house.state.storyAnswer; const priorWorker = house.state.workerAnswer;
  const st = await db.stories.create({ title: 'retry while reading' });
  await db.messages.append(st.id, { role: 'user', text: 'We wait in the hall.' });
  await db.messages.append(st.id, { role: 'assistant', text: H + 'The hall was cold and nobody spoke.' });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await until(() => !env.ctx.chat.isBusy() && !q('.msg-pending'), 'the house free', 20000);
  let release; const held = new Promise((r) => { release = r; });
  const answerFor = (name) => JSON.stringify({ mutations: [{ type: 'presence.enter', name }], brief: { pressure: [], ripe: [], twb: null }, deltas: [] });
  let heldCalls = 0;
  try {
    house.state.workerAnswer = (body) => {
      const text = JSON.stringify(body);
      if (/OLDPAGE-MARK/.test(text)) { heldCalls += 1; return held.then(() => answerFor('Ghost')); }
      if (/NEWPAGE-MARK/.test(text)) return answerFor('Lin');
      return JSON.stringify({ mutations: [], brief: { pressure: [], ripe: [], twb: null }, deltas: [] });
    };
    house.state.storyAnswer = () => H + 'OLDPAGE-MARK Ghost waits at the door, dripping.';
    type(q('#composer-input'), 'I knock.'); submit(q('#composer'));
    await until(() => heldCalls > 0, 'a reader reading the page (the light working)', 20000);
    /* Try again while it reads */
    house.state.storyAnswer = () => H + 'NEWPAGE-MARK Lin opens the door and lets the rain in.';
    await tellerIdle('the page landed');
    tryAgain();
    await until(async () => { const a = (await db.messages.list(st.id)).filter((m) => m.role === 'assistant' && !m.hidden).pop(); const t = a && (Array.isArray(a.swipes) && a.swipes.length ? a.swipes[Number.isFinite(a.swipeIdx) ? a.swipeIdx : a.swipes.length - 1].text : a.text); return /NEWPAGE-MARK/.test(t || '') && !env.ctx.chat.isBusy(); }, 'the new page landed', 30000);
    /* the old reader answers now — after its page was let go */
    release();
    await until(() => queuedCount(st.id) === 0 && !workIsRunning(st.id), 'every reader settled', 40000);
    await tick(300);
    const s = await loadState(st.id);
    const here = (s.present || []).map((p) => p.name);
    assert(!here.includes('Ghost') && !Object.keys(s.characters || {}).includes('Ghost'), 'the replaced page’s reader wrote nothing: ' + here.join(', '));
    assert(here.includes('Lin'), 'the new page’s reading stands: ' + here.join(', '));
    const users = (await db.messages.list(st.id)).filter((m) => m.role === 'user' && m.text === 'I knock.');
    eq(users.length, 1, 'his message once');
  } finally {
    release && release();
    house.state.storyAnswer = priorStory; house.state.workerAnswer = priorWorker;
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-127 A BRANCH WHILE THE READERS ARE STILL ON THE NEWEST PAGE: the branch re-reads that page itself from the ledger before its turn (M112/M506) — its reading stands in the branch, the origin’s held reader lands only in the origin; a branch from a settled tale’s newest page re-reads nothing', async () => {
  const before = errors.length;
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  const { loadState } = await import('../../js/engine/state.js');
  const H = '[The hall — Monday, March 3, 2025 | 09:05 | clear | coat | by the door]\n\n';
  const priorStory = house.state.storyAnswer; const priorWorker = house.state.workerAnswer;
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 }); /* run alone */
  const st = await db.stories.create({ title: 'branch while reading' });
  await db.stories.update(st.id, { brief: 'Ghost and Lin are two guards at the hall.' });
  await db.messages.append(st.id, { role: 'user', text: 'We wait in the hall.' });
  await db.messages.append(st.id, { role: 'assistant', text: H + 'The hall was cold and nobody spoke.' });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await until(() => !env.ctx.chat.isBusy() && !q('.msg-pending'), 'the house free', 20000);
  let release; const held = new Promise((r) => { release = r; });
  const answerFor = (name) => JSON.stringify({ mutations: [{ type: 'presence.enter', name }], brief: { pressure: [], ripe: [], twb: null }, deltas: [] });
  let pageCalls = 0; let calls = 0; let branching = false;
  try {
    house.state.workerAnswer = (body) => {
      calls += 1;
      const text = JSON.stringify(body);
      if (/OLDPAGE-MARK/.test(text)) {
        pageCalls += 1;
        if (pageCalls === 1) return held.then(() => answerFor('Ghost')); /* the origin's page reader, held — its later readers wait behind it */
        if (branching) return answerFor('Lin'); /* the branch's own reading of the same page (the origin's queue is stuck behind the held read) */
      }
      return JSON.stringify({ mutations: [], brief: { pressure: [], ripe: [], twb: null }, deltas: [] });
    };
    house.state.storyAnswer = () => H + 'OLDPAGE-MARK Ghost waits at the door, dripping.';
    type(q('#composer-input'), 'I knock.'); submit(q('#composer'));
    await until(() => pageCalls > 0, 'a reader reading the page (the light working)', 20000);
    await until(() => !env.ctx.chat.isBusy(), 'the page landed', 20000);
    await env.window.__cozy.chat.renderThread({ structural: true });
    await tick(200);
    const pagesNow = assistantPages();
    branching = true;
    click(q('.msg-act[data-act="branch"]', pagesNow[pagesNow.length - 1]));
    await until(async () => (await storyId()) !== st.id, 'the branch is open (after the eight-second wait)', 30000);
    const bid = await storyId();
    const branch = await db.stories.get(bid);
    assert(branch && !branch.building, 'the branch is whole');
    await until(() => pageCalls >= 2, 'the branch reads its last page itself, while the origin’s reader is still held', 30000);
    await until(() => queuedCount(bid) === 0 && !workIsRunning(bid), 'the branch’s readers settled', 40000);
    await tick(300);
    const bs = await loadState(bid);
    const bhere = (bs.present || []).map((p) => p.name);
    assert(bhere.includes('Lin') && !bhere.includes('Ghost'), 'the branch holds its own reading of the page: ' + bhere.join(', '));
    const os0 = await loadState(st.id);
    assert(!(os0.present || []).some((p) => p.name === 'Lin'), 'the branch’s reading never reached the origin');
    /* the origin's held reader answers now — into the origin only */
    branching = false;
    release();
    await until(() => queuedCount(st.id) === 0 && !workIsRunning(st.id), 'the origin’s readers settled', 40000);
    await tick(300);
    const os = await loadState(st.id);
    const ohere = (os.present || []).map((p) => p.name);
    assert(ohere.includes('Ghost') && !ohere.includes('Lin'), 'the origin holds its own reader’s words: ' + ohere.join(', '));
    const bs2 = await loadState(bid);
    assert(!(bs2.present || []).some((p) => p.name === 'Ghost'), 'the origin’s late reader wrote nothing into the branch');
    eq((await db.messages.list(bid)).filter((m) => m.role === 'assistant' && !m.hidden).length, 2, 'the branch has its two pages');
    /* a settled tale: a branch from its newest page carries the ledger as it stands and asks no reader */
    const callsBefore = calls; const pageCallsBefore = pageCalls;
    await env.window.__cozy.chat.renderThread({ structural: true });
    await tick(200);
    const bpages = assistantPages();
    click(q('.msg-act[data-act="branch"]', bpages[bpages.length - 1]));
    await until(async () => (await storyId()) !== bid, 'the second branch is open', 30000);
    const bid2 = await storyId();
    await tick(500);
    await until(() => queuedCount(bid2) === 0 && !workIsRunning(bid2), 'nothing left to settle', 20000);
    eq(pageCalls, pageCallsBefore, 'a settled tale’s newest page is not read again');
    eq(calls, callsBefore, 'no reader was sent at all');
    const b2 = await loadState(bid2);
    assert((b2.present || []).some((p) => p.name === 'Lin'), 'the second branch carries the ledger exactly');
  } finally {
    release && release();
    house.state.storyAnswer = priorStory; house.state.workerAnswer = priorWorker;
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-128 ONE MAN, ONE NAME, ON OPENING: a tale whose ledger holds "the courier" beside "Hachigorō" (the role named in apposition only in a fact and a loose end) opens with one man in the room — the descriptor joined onto his page, the courtyard’s books unbroken (M509-2)', async () => {
  const before = errors.length;
  const { loadState, saveState, emptyState } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const st = await db.stories.create({ title: 'the courier who was two men' });
  await db.stories.update(st.id, { createdAt: Date.now() - 10 * 60 * 1000 }); /* an older tale: the opening heals run */
  const H = '[Tenth Division courtyard — Sunday, Hanami 5, 1001 | 12:15 | clear | shihakushō | before the bench]\n\n';
  await db.messages.append(st.id, { role: 'user', text: 'I wait for the courier.' });
  await db.messages.append(st.id, { role: 'assistant', text: H + 'Hachigorō stood between Sentarō and Kiyone, the paper gone from his hands. The courtyard watched.' });
  let ledger = applyMutations({ ...emptyState(), page: 0 }, [
    { type: 'mc.set', name: 'Jovan Oda' }, { type: 'place.set', name: 'Tenth Division courtyard' }, { type: 'presence.enter', name: 'Jovan Oda' },
    { type: 'people.set', name: 'Hachigorō', field: 'core', text: 'sitting with his back to the wall, a borrowed straw hat low over his face, turning a folded paper over in his hands' },
    { type: 'presence.enter', name: 'Hachigorō', position: 'walking toward the mess' },
    { type: 'people.set', name: 'the courier', field: 'state', text: 'Hauled along the mess path by Sentarō’s grip on his sleeve' },
    { type: 'presence.enter', name: 'the courier', position: 'hauled along' },
    { type: 'people.set', name: 'Suì-Fēng', field: 'threads', text: 'The receiving clerk’s cipher has been demanded of the postmaster under threat — the trail to the courier Hachigorō, five days gone, is now hers to run.' },
    { type: 'knowledge.add', name: 'Byakuya', fact: 'saw the courier Hachigorō ride into the Tenth’s courtyard and call out that he carried something meant for the Thirteenth’s desk' },
    { type: 'knowledge.add', name: 'Hachigorō', fact: 'rode into a battlefield that had already ended' },
  ]).state;
  ledger.readTo = 0;
  await saveState(st.id, ledger);
  eq(ledger.present.map((p) => p.name).join(','), 'Jovan Oda,Hachigorō,the courier', 'fixture: two men');
  /* the last page's readers finished: its version checkpoint stands, so the opening heals (not a resume) */
  { const { saveVersionStates } = await import('../../js/engine/state.js'); const last = (await db.messages.list(st.id)).filter((m) => m.role === 'assistant').pop(); await saveVersionStates(st.id, { [last.id + ':0']: JSON.parse(JSON.stringify(ledger)) }); }
  /* opened the way he opens a tale — what tapping it on the shelf does */
  await env.ctx.chat.openStory(st.id);
  await until(async () => (await storyId()) === st.id, 'the tale is open', 10000);
  await until(async () => (await loadState(st.id)).present.length === 2, 'the opening joins them', 20000);
  const after = await loadState(st.id);
  eq(after.present.map((p) => p.name).join(','), 'Jovan Oda,Hachigorō', 'one man in the room');
  assert(!after.characters['the courier'] && after.characters['Hachigorō'], 'one page');
  assert((after.knowledge['Hachigorō'] || []).some((k) => /battlefield/.test(k.fact)), 'his book is his');
  assert((after.knowledge['Byakuya'] || []).some((k) => /saw Hachigorō ride into/.test(k.fact)), 'the courtyard’s books read on, the name said once: ' + JSON.stringify((after.knowledge['Byakuya'] || []).map((k) => k.fact)));
  /* and after a page, when the opening could not (the readers were still out): the two stand again by a hand on the
   * store; the next page's upkeep joins them */
  const again = await loadState(st.id);
  again.present.push({ name: 'the courier', position: 'on the path' });
  again.characters['the courier'] = { core: '', state: 'hauled along the path', arc: '', threads: [] };
  again.knowledge['Kiyone'] = [{ fact: 'heard the courier Hachigorō say the paper never arrived', atTurn: 2 }];
  await saveState(st.id, again);
  eq((await loadState(st.id)).present.length, 3, 'fixture: two men again');
  const priorStory = house.state.storyAnswer;
  house.state.storyAnswer = () => H + 'The courtyard held its breath while Hachigorō was walked toward the mess.';
  try {
    type(q('#composer-input'), 'I watch him go.'); submit(q('#composer'));
    await until(() => assistantPages().length >= 2 && !env.ctx.chat.isBusy(), 'the page', 20000);
    await settled();
    await until(async () => !(await loadState(st.id)).present.some((p) => p.name === 'the courier'), 'the page’s upkeep joins them', 20000);
  } finally { house.state.storyAnswer = priorStory; }
  const last = await loadState(st.id);
  assert(last.present.some((p) => p.name === 'Hachigorō') && !last.present.some((p) => p.name === 'the courier') && !last.characters['the courier'], 'one man in the room after the page (the walk’s own reader may have let Liara in): ' + last.present.map((p) => p.name).join(','));
  assert((last.knowledge['Kiyone'] || []).some((k) => /heard Hachigorō say/.test(k.fact)), 'her book reads on');
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-129 TRY AGAIN REWINDS THE LEDGER TO BEFORE THE PAGE: the storyteller’s request for the retry carries the hour and the room as they stood before the page, never the page’s own reads (M21, M72)', async () => {
  const before = errors.length;
  const { loadState } = await import('../../js/engine/state.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const st = await db.stories.create({ title: 'retry rewinds' });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await until(() => !env.ctx.chat.isBusy(), 'free', 20000);
  const priorStory = house.state.storyAnswer; const priorWorker = house.state.workerAnswer;
  const H = (hh, mm) => '[The kitchen — Monday, March 3, 2025 | ' + hh + ':' + mm + ' | clear | coat | by the stove]\n\n';
  const seen = [];
  let hour = ['09', '05']; let who = 'Mara Vell';
  try {
    house.state.workerAnswer = (body, sys) => (/keep the ledger/i.test(sys) ? JSON.stringify({ mutations: [{ type: 'presence.enter', name: who, position: 'by the stove' }], brief: { pressure: [], ripe: [], twb: null }, deltas: [] }) : '{"mutations":[],"deltas":[],"findings":[],"issues":[]}');
    house.state.storyAnswer = (body) => { seen.push(notesInBody(body)); /* M510-37: the notes, above the story */ return H(hour[0], hour[1]) + who + ' came in and stood by the stove. The kettle ticked.'; };
    /* page one: 09:05, Mara in */
    type(q('#composer-input'), 'I put the kettle on.'); submit(q('#composer'));
    await until(() => assistantPages().length >= 1 && !env.ctx.chat.isBusy(), 'page one', 20000);
    await settled();
    hour = ['09', '20']; who = 'Tobin Ashcombe';
    /* page two: 09:20, Tobin in */
    type(q('#composer-input'), 'I wait.'); submit(q('#composer'));
    await until(() => assistantPages().length >= 2 && !env.ctx.chat.isBusy(), 'page two', 20000);
    await settled(); await readersDone(st.id);
    const { renderClock } = await import('../../js/engine/clock.js');
    const after2 = await loadState(st.id);
    assert(/09:20/.test(renderClock(after2.clock)), 'page two’s hour stands: ' + renderClock(after2.clock));
    assert(after2.present.some((p) => p.name === 'Tobin Ashcombe'), 'Tobin is in after page two');
    /* try again on page two: the request must carry the ledger as it stood before page two — 09:05, Mara here, Tobin not */
    hour = ['09', '30']; who = 'Nell Pike';
    tryAgain(); /* M675: “try again” under his newest message (the footer’s link is gone) */
    await until(() => seen.length >= 3, 'the retry’s request went out', 30000);
    const req = seen[seen.length - 1];
    assert(/The hour: [^\n]*09:05/.test(req), 'the retry is told the hour BEFORE the page (09:05), not the page’s own (09:20): ' + (req.match(/The hour:[^\n]*/) || [''])[0]);
    assert(/Here now:[^\n]*Mara Vell/.test(req) && !/Here now:[^\n]*Tobin Ashcombe/.test(req), 'and the room as it stood before the page: ' + (req.match(/Here now:[^\n]*/) || [''])[0]);
    await until(() => !env.ctx.chat.isBusy(), 'the new version landed', 20000);
    await settled(); await readersDone(st.id);
    const after3 = await loadState(st.id);
    assert(/09:30/.test(renderClock(after3.clock)), 'the new version’s hour stands: ' + renderClock(after3.clock));
    assert(after3.present.some((p) => p.name === 'Nell Pike') && !after3.present.some((p) => p.name === 'Tobin Ashcombe'), 'the new version’s reads, not the old one’s: ' + after3.present.map((p) => p.name).join(','));
  } finally { house.state.storyAnswer = priorStory; house.state.workerAnswer = priorWorker; }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

