test('DOM-131 TRY AGAIN WHILE THE OLD PAGE’S LATER READERS (world agent, scribe, auditor) ARE STILL OUT: the retry carries the hour before the page; when the old readers answer late they write nothing over the new version', async () => {
  const before = errors.length;
  const { loadState } = await import('../../js/engine/state.js');
  const { renderClock } = await import('../../js/engine/clock.js');
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  await db.settings.set('worldAgent', true);
  const st = await db.stories.create({ title: 'retry under slow readers' });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await until(() => !env.ctx.chat.isBusy(), 'free', 20000);
  const priorStory = house.state.storyAnswer; const priorWorker = house.state.workerAnswer;
  const H = (hh, mm) => '[The kitchen — Monday, March 3, 2025 | ' + hh + ':' + mm + ' | clear | coat | by the stove]\n\n';
  const seen = [];
  let hour = ['09', '05']; let who = 'Mara Vell'; let holdLate = false; let release; const held = new Promise((r) => { release = r; }); let heldCalls = 0;
  try {
    house.state.workerAnswer = (body, sys) => {
      if (/keep the ledger/i.test(sys)) return JSON.stringify({ mutations: [{ type: 'presence.enter', name: who, position: 'by the stove' }], brief: { pressure: [], ripe: [], twb: null }, deltas: [] });
      const late = '{"mutations":[{"type":"offscreen.set","name":"Kim","location":"her flat","activity":"scrolling","stance":"busy"}],"brief":{"pressure":[],"ripe":[],"twb":null},"deltas":[{"name":"Tobin Ashcombe","state":"still by the stove, late word"}],"findings":[],"issues":[]}';
      if (holdLate) { heldCalls += 1; return held.then(() => late); }
      return '{"mutations":[],"deltas":[],"findings":[],"issues":[]}';
    };
    house.state.storyAnswer = (body) => { seen.push(notesInBody(body)); /* M510-37: the notes, above the story */ return H(hour[0], hour[1]) + who + ' came in and stood by the stove. The kettle ticked.'; };
    type(q('#composer-input'), 'I put the kettle on.'); submit(q('#composer'));
    await until(() => assistantPages().length >= 1 && !env.ctx.chat.isBusy(), 'page one', 20000);
    await settled();
    /* M649 (found by running a failed gate down, not by rerunning it): settled() waits for the page and the house — NOT
     * for page one's READERS. When one of them was still out as the holding began, it was the one held: page two's page
     * reader waited behind it in the chain, the hour never landed (twenty seconds were given it, six times of six), and
     * "a later reader of page two is out" was a reader of page one. The scenario means page two's readers: page one's
     * are waited for first. */
    { const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js'); await until(() => queuedCount(st.id) === 0 && !workIsRunning(st.id), 'page one’s readers', 40000); }
    /* page two: its page reader answers at once; its later readers are held */
    hour = ['09', '20']; who = 'Tobin Ashcombe'; holdLate = true;
    type(q('#composer-input'), 'I wait.'); submit(q('#composer'));
    await until(() => assistantPages().length >= 2 && !env.ctx.chat.isBusy(), 'page two', 20000);
    await until(() => heldCalls > 0, 'a later reader of page two is out', 20000);
    await until(async () => /09:20/.test(renderClock((await loadState(st.id)).clock)), 'the page reader landed page two’s hour', 20000); /* waited for, not looked at after a fixed 300 ms */
    /* Try again while they are still out (the app waits five seconds for them, then rewinds) */
    hour = ['09', '30']; who = 'Nell Pike'; holdLate = false;
    tryAgain();
    await until(() => seen.length >= 3, 'the retry’s request went out', 40000);
    const req = seen[seen.length - 1];
    assert(/The hour: [^\n]*09:05/.test(req), 'the retry is told the hour BEFORE the page (09:05): ' + (req.match(/The hour:[^\n]*/) || [''])[0]);
    assert(/Here now:[^\n]*Mara Vell/.test(req) && !/Here now:[^\n]*Tobin Ashcombe/.test(req), 'and the room before the page: ' + (req.match(/Here now:[^\n]*/) || [''])[0]);
    await until(() => !env.ctx.chat.isBusy(), 'the new version landed', 20000);
    /* the old readers answer now, late — they stood before the new version’s in the queue */
    release();
    await tick(1500);
    await until(() => queuedCount(st.id) === 0 && !workIsRunning(st.id), 'everything settled', 40000);
    await until(async () => /09:30/.test(renderClock((await loadState(st.id)).clock)), 'the new version’s hour stands', 20000);
    const last = await loadState(st.id);
    assert(/09:30/.test(renderClock(last.clock)), 'the old page’s late readers did not put its hour back: ' + renderClock(last.clock));
    assert(!last.present.some((p) => p.name === 'Tobin Ashcombe') && last.present.some((p) => p.name === 'Nell Pike'), 'nor its room: ' + last.present.map((p) => p.name).join(','));
    assert(!(last.offscreen && last.offscreen.Kim), 'nor its late world (Kim seated by the old page’s world agent)');
  } finally { release && release(); house.state.storyAnswer = priorStory; house.state.workerAnswer = priorWorker; }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-132 A REWIND IS CHECKED WHOLE, NEVER PATCHED: when a fold keeps the replaced page’s hour AND its walk-in (both stamped on the page before, by a hand on the store), the previous page’s header shows the fold wrong and the WHOLE ledger of the moment before the page is restored — the retry is told that page’s hour and its room, not a corrected hour over the wrong room (M509-9)', async () => {
  const before = errors.length;
  const { loadState, saveState } = await import('../../js/engine/state.js');
  const { renderClock } = await import('../../js/engine/clock.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const st = await db.stories.create({ title: 'checked whole' });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await until(() => !env.ctx.chat.isBusy(), 'free', 20000);
  const priorStory = house.state.storyAnswer; const priorWorker = house.state.workerAnswer;
  const H = (hh, mm) => '[The kitchen — Monday, March 3, 2025 | ' + hh + ':' + mm + ' | clear | coat | by the stove]\n\n';
  const seen = [];
  let hour = ['09', '05']; let who = 'Mara Vell';
  try {
    house.state.workerAnswer = (body, sys) => (/keep the ledger/i.test(sys) ? JSON.stringify({ mutations: [{ type: 'presence.enter', name: who, position: 'by the stove' }], brief: { pressure: [], ripe: [], twb: null }, deltas: [] }) : '{"mutations":[],"deltas":[],"findings":[],"issues":[]}');
    house.state.storyAnswer = (body) => { seen.push(notesInBody(body)); /* M510-37: the notes, above the story */ return H(hour[0], hour[1]) + who + ' came in. The kettle ticked.'; };
    type(q('#composer-input'), 'I put the kettle on.'); submit(q('#composer'));
    await until(() => assistantPages().length >= 1 && !env.ctx.chat.isBusy(), 'page one', 20000);
    await settled();
    hour = ['09', '20']; who = 'Tobin Ashcombe';
    type(q('#composer-input'), 'I wait.'); submit(q('#composer'));
    await until(() => assistantPages().length >= 2 && !env.ctx.chat.isBusy(), 'page two', 20000);
    await settled(); await readersDone(st.id);
    /* a hand on the store: page two’s clock AND its walk-in re-stamped on page one — a fold to page one keeps 09:20 and Tobin */
    const broken = await loadState(st.id);
    let bent = 0;
    for (const e of broken.journal) if (e && e.m && e.p === 1 && (e.m.type === 'clock.set' || (e.m.type === 'presence.enter' && e.m.name === 'Tobin Ashcombe'))) { e.p = 0; bent += 1; }
    assert(bent >= 2, 'fixture: page two’s clock and walk-in re-stamped on page one: ' + bent);
    await saveState(st.id, broken);
    hour = ['09', '30']; who = 'Nell Pike';
    tryAgain();
    await until(() => seen.length >= 3, 'the retry’s request went out', 30000);
    const req = seen[seen.length - 1];
    assert(/The hour: [^\n]*09:05/.test(req), 'the retry is told page one’s hour: ' + (req.match(/The hour:[^\n]*/) || [''])[0]);
    const here = (req.match(/Here now:[^\n]*/) || [''])[0];
    assert(/Mara Vell/.test(here) && !/Tobin Ashcombe/.test(here), 'and page one’s room — the whole ledger of that moment, not an hour over the wrong room: ' + here);
    await until(() => !env.ctx.chat.isBusy(), 'the new version landed', 20000);
    await settled(); await readersDone(st.id);
    const last = await loadState(st.id);
    assert(/09:30/.test(renderClock(last.clock)), 'the new version’s hour stands');
    assert(last.present.some((p) => p.name === 'Nell Pike') && !last.present.some((p) => p.name === 'Tobin Ashcombe'), 'the new version’s room: ' + last.present.map((p) => p.name).join(','));
  } finally { house.state.storyAnswer = priorStory; house.state.workerAnswer = priorWorker; }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-133 A JOIN SURVIVES TRY AGAIN: a tale whose pages wrote "the courier" and "Hachigorō" as two men long before the house could join them is joined on opening (stamped on the newest page); a Try again folds to the page before — and the fold joins them again, so the retry’s request has one man (M509-8)', async () => {
  const before = errors.length;
  const { loadState, saveState, emptyState, snapshotState, markPageRead, saveVersionStates } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const st = await db.stories.create({ title: 'the courier through a retry' });
  await db.stories.update(st.id, { createdAt: Date.now() - 10 * 60 * 1000 });
  const H = (mm) => '[The courtyard — Monday, March 3, 2025 | 09:' + mm + ' | clear | coat | by the gate]\n\n';
  /* three pages, read by a house that had no join yet: page 0 writes both men, page 1 the fact naming him, page 2 nothing */
  let state = applyMutations({ ...emptyState(), page: 0 }, [{ type: 'mc.set', name: 'Jovan Oda' }, { type: 'place.set', name: 'The courtyard' }, { type: 'presence.enter', name: 'Jovan Oda' }]).state;
  const reads = [
    [{ type: 'presence.enter', name: 'the courier', position: 'on the path' }, { type: 'presence.enter', name: 'Hachigorō', position: 'at the gate' }, { type: 'people.set', name: 'Hachigorō', field: 'core', text: 'a rider with a straw hat' }],
    [{ type: 'knowledge.add', name: 'Byakuya', fact: 'saw the courier Hachigorō ride into the courtyard with the paper' }],
    [{ type: 'knowledge.add', name: 'Byakuya', fact: 'saw the paper change hands' }],
  ];
  let lastId = null;
  for (let k = 0; k < 3; k += 1) {
    const u = await db.messages.append(st.id, { role: 'user', text: 'I watch, page ' + k + '.' });
    state.page = k;
    await snapshotState(st.id, u.id, state);
    const a = await db.messages.append(st.id, { role: 'assistant', text: H(String(5 + k * 10).padStart(2, '0')) + 'The courtyard held its breath, page ' + k + '.' });
    state = applyMutations(state, [{ type: 'clock.set', year: 2025, month: 3, day: 3, hour: 9, minute: 5 + k * 10 }, ...reads[k]]).state;
    markPageRead(state, k);
    await saveState(st.id, state);
    lastId = a.id;
  }
  await saveVersionStates(st.id, { [lastId + ':0']: JSON.parse(JSON.stringify(state)) });
  eq((await loadState(st.id)).present.map((p) => p.name).join(','), 'Jovan Oda,the courier,Hachigorō', 'fixture: two men, journaled on page 0, the naming fact on page 1');
  /* opened the way tapping the shelf opens it: the opening heal joins them, stamped on the newest page */
  await env.ctx.chat.openStory(st.id);
  await until(async () => (await storyId()) === st.id, 'open', 10000);
  await until(async () => !(await loadState(st.id)).present.some((p) => p.name === 'the courier'), 'the opening joined them', 20000);
  const priorStory = house.state.storyAnswer; const priorWorker = house.state.workerAnswer;
  const seen = [];
  try {
    house.state.workerAnswer = () => '{"mutations":[],"brief":{"pressure":[],"ripe":[],"twb":null},"deltas":[],"findings":[],"issues":[]}';
    house.state.storyAnswer = (body) => { seen.push(notesInBody(body)); /* M510-37: the notes, above the story */ return H('40') + 'The kettle ticked.'; };
    tryAgain();
    await until(() => seen.length >= 1, 'the retry’s request went out', 30000);
    const here = (seen[0].match(/Here now:[^\n]*/) || [''])[0];
    assert(/Hachigorō/.test(here) && !/the courier/.test(here), 'the retry is told one man: ' + here);
    assert(/The hour: [^\n]*09:15/.test(seen[0]), 'and the hour of the page before: ' + (seen[0].match(/The hour:[^\n]*/) || [''])[0]);
    await until(() => !env.ctx.chat.isBusy(), 'the new version landed', 20000);
    await settled(); await readersDone(st.id);
    const last = await loadState(st.id);
    assert(!last.present.some((p) => p.name === 'the courier') && !last.characters['the courier'], 'one man after the new version: ' + last.present.map((p) => p.name).join(','));
  } finally { house.state.storyAnswer = priorStory; house.state.workerAnswer = priorWorker; }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-134 NO CHECKPOINT OF THAT MOMENT: the fold keeps the replaced page’s hour and walk-in AND the boundary checkpoint before that page is gone — the house reads the page before again by itself, and the retry is built from that read: its hour, its room; nothing is asked of the writer (M509-10)', async () => {
  const before = errors.length;
  const { loadState, saveState, loadSnapshots, saveSnapshots } = await import('../../js/engine/state.js');
  const { renderClock } = await import('../../js/engine/clock.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const st = await db.stories.create({ title: 'rebuilt by itself' });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await until(() => !env.ctx.chat.isBusy(), 'free', 20000);
  const priorStory = house.state.storyAnswer; const priorWorker = house.state.workerAnswer;
  const H = (hh, mm) => '[The kitchen — Monday, March 3, 2025 | ' + hh + ':' + mm + ' | clear | coat | by the stove]\n\n';
  const seen = []; let reads = 0;
  let hour = ['09', '05']; let who = 'Mara Vell';
  try {
    /* the page reader answers by the page it is handed: Mara for page one, Tobin for page two */
    house.state.workerAnswer = (body, sys) => {
      if (!/keep the ledger/i.test(sys)) return '{"mutations":[],"deltas":[],"findings":[],"issues":[]}';
      reads += 1;
      const page = String((body.messages.find((m) => m.role === 'user') || {}).content || '');
      const name = /Tobin Ashcombe/.test(page) ? 'Tobin Ashcombe' : /Nell Pike/.test(page) ? 'Nell Pike' : 'Mara Vell';
      return JSON.stringify({ mutations: [{ type: 'presence.enter', name, position: 'by the stove' }], brief: { pressure: [], ripe: [], twb: null }, deltas: [] });
    };
    house.state.storyAnswer = (body) => { seen.push(notesInBody(body)); /* M510-37: the notes, above the story */ return H(hour[0], hour[1]) + who + ' came in. The kettle ticked.'; };
    type(q('#composer-input'), 'I put the kettle on.'); submit(q('#composer'));
    await until(() => assistantPages().length >= 1 && !env.ctx.chat.isBusy(), 'page one', 20000);
    await settled();
    hour = ['09', '20']; who = 'Tobin Ashcombe';
    type(q('#composer-input'), 'I wait.'); submit(q('#composer'));
    await until(() => assistantPages().length >= 2 && !env.ctx.chat.isBusy(), 'page two', 20000);
    await settled(); await readersDone(st.id);
    /* a hand on the store: page two’s clock and walk-in re-stamped on page one, AND the checkpoint before page two gone */
    const broken = await loadState(st.id);
    for (const e of broken.journal) if (e && e.m && e.p === 1 && (e.m.type === 'clock.set' || (e.m.type === 'presence.enter' && e.m.name === 'Tobin Ashcombe'))) e.p = 0;
    await saveState(st.id, broken);
    const users = (await db.messages.list(st.id)).filter((m) => m.role === 'user');
    const snaps = await loadSnapshots(st.id);
    assert(snaps.some((e) => e.id === users[1].id), 'fixture: the checkpoint before page two stood');
    await saveSnapshots(st.id, snaps.filter((e) => e.id !== users[1].id));
    const readsBefore = reads;
    hour = ['09', '30']; who = 'Nell Pike';
    tryAgain();
    await until(() => seen.length >= 3, 'the retry’s request went out', 60000);
    assert(reads > readsBefore, 'the house read page one again by itself before building the retry: ' + reads + ' vs ' + readsBefore);
    const req = seen[seen.length - 1];
    assert(/The hour: [^\n]*09:05/.test(req), 'the retry is told page one’s hour: ' + (req.match(/The hour:[^\n]*/) || [''])[0]);
    const here = (req.match(/Here now:[^\n]*/) || [''])[0];
    assert(/Mara Vell/.test(here) && !/Tobin Ashcombe/.test(here), 'and page one’s room, read fresh: ' + here);
    await until(() => !env.ctx.chat.isBusy(), 'the new version landed', 20000);
    await settled(); await readersDone(st.id);
    const last = await loadState(st.id);
    assert(/09:30/.test(renderClock(last.clock)) && last.present.some((p) => p.name === 'Nell Pike') && !last.present.some((p) => p.name === 'Tobin Ashcombe'), 'the new version stands: ' + renderClock(last.clock) + ' ' + last.present.map((p) => p.name).join(','));
  } finally { house.state.storyAnswer = priorStory; house.state.workerAnswer = priorWorker; }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-135 THE DRAWER SAYS WHICH PAGE THE LEDGER BELONGS TO: even with the story after a page is read; and when a page is on the shelf unread it says the readers are on the rest (M509-11)', async () => {
  const before = errors.length;
  const { loadState, saveState } = await import('../../js/engine/state.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const st = await db.stories.create({ title: 'the standing line' });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await until(() => !env.ctx.chat.isBusy(), 'free', 20000);
  const priorStory = house.state.storyAnswer; const priorWorker = house.state.workerAnswer;
  const H = '[The kitchen — Monday, March 3, 2025 | 09:05 | clear | coat | by the stove]\n\n';
  try {
    house.state.workerAnswer = () => '{"mutations":[],"brief":{"pressure":[],"ripe":[],"twb":null},"deltas":[],"findings":[],"issues":[]}';
    house.state.storyAnswer = () => H + 'The kettle ticked.';
    globalThis.__cozyLedgerBackoffMs = 500; /* M583: the pause between looks for unread pages, shortened for the walk (a minute in the house) */
    type(q('#composer-input'), 'I put the kettle on.'); submit(q('#composer'));
    await until(() => assistantPages().length >= 1 && !env.ctx.chat.isBusy(), 'page one', 20000);
    await settled();
    click(q('#btn-ledger'));
    await until(() => q('#ledger-standing') && /page 1 of 1 — even with the story/.test(q('#ledger-standing').textContent), 'even with the story', 10000);
    /* a page appended by a hand, unread: the line says the readers are on the rest */
    await db.messages.append(st.id, { role: 'user', text: 'I wait.' });
    await db.messages.append(st.id, { role: 'assistant', text: H + 'Nobody came.' });
    await env.ctx.chat.renderThread({ structural: true });
    click(q('#btn-drawer-close')); await tick(50); click(q('#btn-ledger'));
    /* the line says "page 1 of 2 — the readers are on the rest" until the house reads the page by itself (it does, unasked),
     * then "page 2 of 2 — even with the story": the ledger is seen catching up, and even */
    const seenLines = new Set();
    try {
      await until(() => { const t = (q('#ledger-standing') || {}).textContent || ''; seenLines.add(t); return /page 2 of 2 — even with the story/.test(t); }, 'the house read the page', 30000);
    } catch (err) {
      /* M583: a failure says what the house was doing — the lines seen, the read marks, the queue, the readers' shelf */
      const stNow = await (await import('../../js/engine/state.js')).loadState(st.id);
      const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
      const { loadWorkerStatus } = await import('../../js/agents/status.js');
      const elsewhere = env.ctx.booksStatus && typeof env.ctx.booksStatus.wroteElsewhereAt === 'function' ? env.ctx.booksStatus.wroteElsewhereAt(st.id) : 'n/a';
      throw new Error(err.message + ' — lines seen: ' + [...seenLines].join(' | ') + ' — readTo ' + stNow.readTo + ', readAhead ' + JSON.stringify(stNow.readAhead) + ', page ' + stNow.page + ' — queued ' + queuedCount(st.id) + ', running ' + workIsRunning(st.id) + ', busy ' + env.ctx.chat.isBusy() + ', replaying ' + env.ctx.chat.isReplaying() + ' — elsewhere ' + elsewhere + ' — shelf ' + JSON.stringify(await loadWorkerStatus(st.id)).slice(0, 300) + ' — house fail ' + JSON.stringify(house.state.fail));
    }
    assert([...seenLines].some((t) => /page 1 of 2 — the readers are on the rest/.test(t) || /page 2 of 2/.test(t)), 'the line named the page throughout: ' + [...seenLines].join(' | '));
    click(q('#btn-drawer-close'));
  } finally { house.state.storyAnswer = priorStory; house.state.workerAnswer = priorWorker; }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-233 A CHANGE THAT LANDS WHILE THE LEDGER IS OPENING IS STILL SHOWN (M639): the drawer draws, then waits a beat before it slides in — a reader that finishes the last page in that beat is not lost; the line that said “the readers are on the rest” becomes “even with the story” by itself', async () => {
  const before = errors.length;
  const { loadState, saveState, notify } = await import('../../js/engine/state.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const H = '[The kitchen — Monday, March 3, 2025 | 09:05 | clear | coat | by the stove]\n\n';
  const st = await db.stories.create({ title: 'the opening beat' });
  await db.stories.update(st.id, { extraction: false, keeper: false }); /* no reader of the house's own moves in this scenario: the change is made by hand, at a known moment */
  await db.messages.append(st.id, { role: 'user', text: 'I put the kettle on.' });
  await db.messages.append(st.id, { role: 'assistant', text: H + 'The kettle ticked.' });
  await db.messages.append(st.id, { role: 'user', text: 'I wait.' });
  await db.messages.append(st.id, { role: 'assistant', text: H + 'Nobody came.' });
  const first = await loadState(st.id); first.readTo = 0; await saveState(st.id, first); /* page one read, page two not yet */
  env.window.__cozy.setActiveStoryId(st.id);
  await env.window.__cozy.chat.renderThread({ structural: true });
  await until(() => !env.ctx.chat.isBusy(), 'free', 20000);
  if (!q('#drawer').hidden) { click(q('#btn-drawer-close')); await until(() => q('#drawer').hidden, 'the ledger closed', 5000); }
  try {
    const done = await loadState(st.id); done.readTo = 1; /* what a reader that has just finished page two writes */
    click(q('#btn-ledger'));
    const hiddenAtChange = q('#drawer').hidden; /* the beat before it slides in */
    await saveState(st.id, done);
    notify(st.id);
    await until(() => !q('#drawer').hidden, 'the ledger shows', 5000);
    await until(() => /page 2 of 2 — even with the story/.test((q('#ledger-standing') || {}).textContent || ''), 'the line catches up by itself (the change landed while the ledger was ' + (hiddenAtChange ? 'still opening' : 'open') + ') — it reads: ' + ((q('#ledger-standing') || {}).textContent || ''), 6000);
  } finally {
    click(q('#btn-drawer-close'));
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

