test('DOM-282 A RENAME OUTLIVES A TRY AGAIN (M681 — the books audit’s B13): his edit renames Kira to Kiyone everywhere — the pages, the record, the ledger; “try again” on the newest page folded the ledger back past the rename, and the ledger knew her as Kira while every page said Kiyone', async () => {
  const before = errors.length;
  const { loadState, saveState } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const H = '[The yard — Monday, March 3, 2025 | 09:00 | clear]\n\n';
  const st = await clockTale('rename then try again', [H + 'Kira poured the tea by the well.', H.replace('09:00', '09:20') + 'Kira laughed at the joke about the bucket.'], { readTo: 1 });
  let led = await loadState(st.id);
  led.page = 0; led = applyMutations(led, [{ type: 'people.set', name: 'Kira', field: 'core', text: 'the innkeeper’s daughter' }]).state;
  led.page = 1; await saveState(st.id, led);
  const prior = { story: house.state.storyAnswer, worker: house.state.workerAnswer };
  try {
    house.state.workerAnswer = () => QUIET_WORKERS;
    const pages = (await db.messages.list(st.id)).filter((m) => m.role === 'assistant');
    const after = pages[0].text.replace('Kira', 'Kiyone');
    await db.messages.update(st.id, pages[0].id, { text: after });
    env.ctx.chat.rippleAfterEdit(await db.stories.get(st.id), pages[0].id, pages[0].text, after);
    await readersDone(st.id, 30000);
    assert((await loadState(st.id)).characters.Kiyone, 'the ledger knows her as Kiyone: ' + Object.keys((await loadState(st.id)).characters));
    assert(/Kiyone laughed/.test((await db.messages.list(st.id)).find((m) => m.id === pages[1].id).text), 'the newest page says Kiyone too');
    house.state.storyAnswer = () => H.replace('09:00', '09:25') + 'Kiyone smiled and set down the cup.';
    env.window.__cozy.setActiveStoryId(st.id);
    await env.window.__cozy.chat.renderThread({ structural: true });
    tryAgain();
    await until(async () => /Kiyone smiled/.test((((await db.messages.list(st.id)).filter((m) => m.role === 'assistant').pop()) || {}).text || ''), 'the page told again', 20000);
    await settled(); await readersDone(st.id, 60000);
    const led2 = await loadState(st.id);
    assert(led2.characters.Kiyone && !led2.characters.Kira, 'after the try again the ledger still knows her as Kiyone: ' + Object.keys(led2.characters).join(', '));
  } finally {
    house.state.storyAnswer = prior.story; house.state.workerAnswer = prior.worker;
    await db.stories.remove(st.id).catch(() => {});
    await env.ctx.chat.refreshStories(true).catch(() => {});
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-283 A SECOND MEND KEEPS THE STORYTELLER’S OWN WORDS — AND HIS OWN, WHEN HE WROTE OVER THE FIRST (M681 — the books audit’s B8): a page the ripple mended twice remembered only the first mend’s words as its earlier words; “the earlier words are a tap away” gave back the house’s words, the storyteller’s gone for good', async () => {
  const before = errors.length;
  const H = '[The yard — Monday, March 3, 2025 | 09:00 | clear]\n\n';
  const st = await clockTale('two mends', [H + 'Kira poured the tea by the well.', H.replace('09:00', '09:20') + 'Kira laughed at the joke about the bucket.']);
  const prior = { worker: house.state.workerAnswer };
  try {
    house.state.workerAnswer = () => QUIET_WORKERS;
    const ids = (await db.messages.list(st.id)).filter((m) => m.role === 'assistant').map((m) => m.id);
    const page = async (i) => (await db.messages.list(st.id)).find((m) => m.id === ids[i]);
    const edit = async (from, to) => {
      const was = (await page(1)).text; const now = was.replace(from, to);
      await db.messages.update(st.id, ids[1], { text: now });
      env.ctx.chat.rippleAfterEdit(await db.stories.get(st.id), ids[1], was, now);
      await readersDone(st.id, 30000);
    };
    const told = H + 'Kira poured the tea by the well.';
    await edit('Kira', 'Kiyone');
    eq((await page(0)).text, H + 'Kiyone poured the tea by the well.', 'the first mend');
    eq((await page(0)).mended.before, told, 'its earlier words: the storyteller’s');
    await edit('Kiyone', 'Kiyo');
    eq((await page(0)).text, H + 'Kiyo poured the tea by the well.', 'the second mend');
    eq((await page(0)).mended.before, told, 'its earlier words are still the storyteller’s, never the first mend’s');
    /* he writes over the mended page himself; the next mend's earlier words are HIS */
    const his = H + 'Kiyo poured the tea by the well, humming.';
    await db.messages.update(st.id, ids[0], { text: his });
    await edit('Kiyo', 'Kiyoko');
    eq((await page(0)).text, H + 'Kiyoko poured the tea by the well, humming.', 'the third mend');
    eq((await page(0)).mended.before, his, 'his own words are the earlier words now');
  } finally {
    house.state.workerAnswer = prior.worker;
    await db.stories.remove(st.id).catch(() => {});
    await env.ctx.chat.refreshStories(true).catch(() => {});
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-275 THE CHOICES ARE MADE FROM THE LEDGER AS THE PAGE LEFT IT (M680 — the books audit): Choices matter asked its helper the moment a page landed, before the page’s own readers had written it into the ledger — so the outcomes were sealed against the room as it stood BEFORE the page: a man the page had just walked out of the yard was still “here now”. It waits for the page’s readers now', async () => {
  const before = errors.length;
  const { saveState, emptyState, loadState } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const keeperWas = await db.settings.get('memoryKeeper');
  const answerWas = house.state.workerAnswer; const storyWas = house.state.storyAnswer;
  await db.settings.set('memoryKeeper', false);
  try {
    const st = await db.stories.create({ title: 'the choices see the page' });
    let ts = Date.now() - 60000;
    const H = '[The yard — Monday, March 3, 2025 | 09:00 | clear]\n\n';
    await db.messages.append(st.id, { role: 'user', text: 'I walk into the yard.', ts: (ts += 100) });
    await db.messages.append(st.id, { role: 'assistant', text: H + 'Rukia and Renji were sparring in the yard when Jovan came in.', ts: (ts += 100) });
    const led = applyMutations({ ...emptyState(), page: 0 }, [{ type: 'mc.set', name: 'Jovan' }, { type: 'place.set', name: 'The yard' }, { type: 'presence.enter', name: 'Jovan' }, { type: 'presence.enter', name: 'Rukia' }, { type: 'presence.enter', name: 'Renji' }]).state;
    led.readTo = 0;
    await saveState(st.id, led);
    await db.stories.update(st.id, { choices: true });
    let choicesAsk = null;
    house.state.storyAnswer = () => H.replace('09:00', '09:10') + 'Renji spat in the dust. "I am done with this," he said, and Renji turned and walked out through the gate, gone. Rukia lowered her sword and looked at Jovan, waiting for his answer.';
    house.state.workerAnswer = (body, sys) => {
      if (/keep the turning points/i.test(sys)) { choicesAsk = String(body.messages.slice(-1)[0].content || ''); return '{"turning":false}'; }
      if (/keep the ledger/i.test(sys)) return JSON.stringify({ mutations: [{ type: 'presence.leave', name: 'Renji', shown: 'Renji turned and walked out through the gate', to: 'out through the yard gate' }] });
      return '{"mutations":[],"deltas":[],"findings":[],"issues":[],"brief":{"pressure":[],"ripe":[],"twb":null}}';
    };
    env.window.__cozy.setActiveStoryId(st.id);
    await env.window.__cozy.chat.renderThread({ structural: true });
    await tick(200);
    type(q('#composer-input'), 'I ask Rukia what that was about.');
    submit(q('#composer'));
    await until(() => choicesAsk !== null, 'the choices helper is asked', 60000);
    await until(() => !env.ctx.chat.isBusy() && queuedCount(st.id) === 0 && !workIsRunning(st.id), 'the readers', 60000);
    eq((await loadState(st.id)).present.map((p) => p.name).sort().join(', '), 'Jovan, Rukia', 'the page reader took Renji out');
    const hereLine = choicesAsk.split('\n').find((l) => /^Here now/.test(l.trim())) || '';
    assert(/Rukia/.test(hereLine) && !/Renji/.test(hereLine), 'the choices helper is told the room as the page left it — got: ' + (hereLine || '(no “Here now” line)'));
  } finally {
    house.state.workerAnswer = answerWas; house.state.storyAnswer = storyWas;
    if (keeperWas === undefined) await db.settings.delete('memoryKeeper'); else await db.settings.set('memoryKeeper', keeperWas);
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-300 HIS “LET IT GO” IS HIS, FOR A SEAT AND FOR A FACTION (M681 — the world audit’s W8 checked, W7): the drawer’s “Let it go” on Kiyone’s elsewhere note — a person with a page, whose note no worker may let go — lets it go and the journal marks it his; a faction now has its own “Let it go”, journaled as his, and says how old its move is', async () => {
  const before = errors.length;
  const { loadState, saveState } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const st = await clockTale('his let go', ['[The yard — Monday, March 3, 2025 | 09:00 | clear]\n\nJovan waited by the well. Across the barracks Kiyone sorted the rosters in the third seats’ office.']);
  let led = await loadState(st.id);
  /* written before the first page (the founder's stamp, -1), so the opening's own reading of page one keeps them */
  led = applyMutations({ ...led, page: -1 }, [{ type: 'people.set', name: 'Kiyone', field: 'core', text: 'third seat of the 13th' }, { type: 'offscreen.set', name: 'Kiyone', location: 'the third seats’ office', activity: 'sorting rosters', stance: 'busy' },
    { type: 'faction.set', name: 'the Black Hand', stance: 'hunting the heir', move: 'burned the granary' }]).state;
  led.page = 0;
  await saveState(st.id, led);
  eq(applyMutations(led, [{ type: 'offscreen.clear', name: 'Kiyone' }]).applied.length, 0, 'fixture: a worker may not let her note go');
  const prior = house.state.workerAnswer;
  try {
    house.state.workerAnswer = () => QUIET_WORKERS;
    await env.ctx.chat.openStory(st.id);
    await tick(300);
    await readersDone(st.id, 30000);
    click(q('#btn-ledger'));
    await until(() => !q('#drawer').hidden, 'the drawer opens');
    await env.ctx.drawer.renderAllRooms(); await tick(350);
    const letGoOf = (re) => qa('#drawer-panels li').filter((li) => re.test(li.textContent)).map((li) => [...li.querySelectorAll('button')].find((b) => b.textContent.trim() === 'Let it go')).find(Boolean);
    click(await until(() => letGoOf(/^Kiyone — /), 'Kiyone’s elsewhere note, with its “Let it go”', 15000));
    await until(async () => !(await loadState(st.id)).offscreen.Kiyone, 'her note let go', 10000);
    const seatGone = [...(await loadState(st.id)).journal].reverse().find((j) => j.m && j.m.type === 'offscreen.clear');
    assert(seatGone && seatGone.m.byHand === true, 'the journal marks the letting-go his: ' + JSON.stringify(seatGone));
    await env.ctx.drawer.renderAllRooms(); await tick(350);
    const facRow = await until(() => letGoOf(/^the Black Hand — /), 'the faction, with its “Let it go”', 15000);
    assert(/last move: burned the granary/.test(facRow.closest('li').textContent), 'its move is shown: ' + facRow.closest('li').textContent);
    click(facRow);
    await until(async () => !Object.keys((await loadState(st.id)).factions || {}).length, 'the faction let go', 10000);
    const facGone = [...(await loadState(st.id)).journal].reverse().find((j) => j.m && j.m.type === 'faction.clear');
    assert(facGone && facGone.m.byHand === true, 'journaled as his: ' + JSON.stringify(facGone));
  } finally {
    if (!q('#drawer').hidden) click(q('#btn-ledger'));
    house.state.workerAnswer = prior;
    await db.stories.remove(st.id).catch(() => {});
    await env.ctx.chat.refreshStories(true).catch(() => {});
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-290 THE PAGE WHOSE MOOD BOARD ITS READER STATED IS MARKED (M681 — the scene audit’s S13): a page read with its board stated marks it; the next page’s reader forgets the board twice — the board is an older page’s, and the auditor is told it may restate it', async () => {
  const before = errors.length;
  const { loadState } = await import('../../js/engine/state.js');
  const { boardStale } = await import('../../js/agents/auditor.js');
  const H = '[The inn — Monday, March 3, 2025 | 18:00 | rain]\n\n';
  const st = await clockTale('the stale board', [H + 'The cart rolled on through the rain.']);
  const prior = { story: house.state.storyAnswer, worker: house.state.workerAnswer };
  try {
    let board = true;
    house.state.workerAnswer = (body, sys) => (/keep the ledger/i.test(sys) ? JSON.stringify({ mutations: board ? [{ type: 'mode.snapshot', flags: ['travel'] }] : [], here: ['Jovan'] }) : QUIET_WORKERS);
    house.state.storyAnswer = () => H.replace('18:00', '18:30') + 'The cart rolled on; the inn was still a mile off.';
    env.window.__cozy.setActiveStoryId(st.id);
    await env.window.__cozy.chat.renderThread({ structural: true });
    type(q('#composer-input'), 'I keep my head down.'); submit(q('#composer'));
    await until(async () => (await db.messages.list(st.id)).filter((m) => m.role === 'assistant').length === 2 && !env.ctx.chat.isBusy(), 'the second page', 20000);
    await settled(); await readersDone(st.id, 60000);
    eq((await loadState(st.id)).moodAt, 1, 'the page whose board its reader stated is marked');
    board = false;
    house.state.storyAnswer = () => H.replace('18:00', '19:10') + 'They had arrived; the innkeeper took their wet cloaks at the door.';
    type(q('#composer-input'), 'I step down from the cart.'); submit(q('#composer'));
    await until(async () => (await db.messages.list(st.id)).filter((m) => m.role === 'assistant').length === 3 && !env.ctx.chat.isBusy(), 'the third page', 20000);
    await settled(); await readersDone(st.id, 60000);
    const led = await loadState(st.id);
    eq(led.moodAt, 1, 'a reader that never stated the board does not mark its page');
    eq(led.mode.travel, true, 'fixture: the board the reader forgot still says travel');
    eq(boardStale(led, 2), true, 'the board is stale for the newest page — the auditor’s to restate');
  } finally {
    house.state.storyAnswer = prior.story; house.state.workerAnswer = prior.worker;
    await db.stories.remove(st.id).catch(() => {});
    await env.ctx.chat.refreshStories(true).catch(() => {});
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-291 THE STORY’S OWN CALENDAR OUTLIVES A TRY AGAIN (M681 — the scene audit’s S11): he names the months and days in the drawer; “try again” on the newest page folded the clock back past them and the real calendar spoke again', async () => {
  const before = errors.length;
  const { loadState } = await import('../../js/engine/state.js');
  const H = '[The yard — Monday, March 3, 2025 | 09:00 | clear]\n\n';
  const st = await clockTale('his calendar', [H + 'Kim waited by the well.', H.replace('09:00', '09:20') + 'Kim drew a bucket up.'], { readTo: 1 });
  const prior = { story: house.state.storyAnswer, worker: house.state.workerAnswer };
  try {
    house.state.workerAnswer = () => QUIET_WORKERS;
    await env.ctx.chat.openStory(st.id);
    await tick(300);
    if (q('#drawer').hidden) click(q('#btn-ledger'));
    click(await until(() => q('#drawer [data-room="scene"]'), 'the scene room', 15000)); /* the room he left it on may be another */
    const cal = await until(() => q('#drawer .calendar-editor'), 'the calendar', 15000);
    const pick = q('select', cal);
    pick.value = 'custom'; pick.dispatchEvent(new env.window.Event('change'));
    await until(async () => (await loadState(st.id)).clock.calendar === 'custom', 'a calendar of its own', 10000);
    const months = await until(() => { const i = q('input[aria-label="The year’s months, in order, comma by comma"]', cal); return i && !i.hidden ? i : null; }, 'the months', 10000);
    type(months, 'Frostfall, Deepwinter, Thawmoon, Seedtide, Bloomrise, Highsun, Emberfall, Harvestide, Leafturn, Mistmoon, Duskfall, Longnight');
    type(q('input[aria-label="The week’s days, in order, comma by comma"]', cal), 'Sunsday, Moonsday, Thornday, Fireday, Windsday, Starday, Restday');
    click([...qa('button', cal)].find((b) => b.textContent === 'Keep the names'));
    await until(async () => ((await loadState(st.id)).clock.monthNames || [])[2] === 'Thawmoon', 'his names', 10000);
    if (!q('#drawer').hidden) click(q('#btn-ledger'));
    house.state.storyAnswer = () => H.replace('09:00', '09:25') + 'Kim drew the bucket up again, slower.';
    env.window.__cozy.setActiveStoryId(st.id);
    await env.window.__cozy.chat.renderThread({ structural: true });
    tryAgain();
    await until(async () => /slower/.test((((await db.messages.list(st.id)).filter((m) => m.role === 'assistant').pop()) || {}).text || ''), 'the page told again', 20000);
    await settled(); await readersDone(st.id, 60000);
    const led = await loadState(st.id);
    eq(led.clock.calendar, 'custom', 'the calendar he chose stands after the try again');
    eq((led.clock.monthNames || [])[2], 'Thawmoon', 'and his names with it');
  } finally {
    if (!q('#drawer').hidden) click(q('#btn-ledger'));
    house.state.storyAnswer = prior.story; house.state.workerAnswer = prior.worker;
    await db.stories.remove(st.id).catch(() => {});
    await env.ctx.chat.refreshStories(true).catch(() => {});
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-310 A VERSION WALKED ON AN OLDER PAGE IS READ AGAIN BY THE PLANS KEEPER (M681 — the books audit’s B1): the version that laid out “the night raid” was left for one that lays out nothing — the raid stood on in the plans keeper’s book (told to the storyteller every page) and the page was never read again; walked back, the raid was never written down again', async () => {
  const before = errors.length;
  const { saveState, emptyState } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  const { PLANS_KEY, loadPlansBook } = await import('../../js/agents/plans.js');
  const { fingerprint36 } = await import('../../js/engine/fingerprint.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const keeperWas = await db.settings.get('memoryKeeper');
  const prior = { worker: house.state.workerAnswer, plans: house.state.plansAnswer };
  await db.settings.set('memoryKeeper', false);
  const H = (t) => '[The yard — Monday, March 3, 2025 | ' + t + ' | clear]\n\n';
  const RAID = H('09:11') + 'Rukia laid out the night raid: Renji draws the guards off at midnight, and Rukia opens the gate on the bell.';
  const SHRUG = H('09:11') + 'Rukia shrugged and went to bed early; nobody spoke of the gate that night.';
  const raid = { title: 'the night raid', by: 'Rukia', goal: 'take the gate', parts: [{ who: 'Renji', does: 'draws the guards off', when: 'at midnight' }, { who: 'Rukia', does: 'opens the gate', when: 'on the bell' }], words: [] };
  const read = [];
  const pagesPart = (body) => String(((body.messages || []).slice(-1)[0] || {}).content || '').split('The pages to read')[1] || '';
  house.state.plansAnswer = (body) => { const p = pagesPart(body); read.push(p); return /night raid/.test(p) ? JSON.stringify({ new: [{ ...raid, page: 4 }], progress: [], closed: [] }) : '{"new":[],"progress":[],"closed":[]}'; };
  house.state.workerAnswer = () => '{"mutations":[],"deltas":[],"findings":[],"issues":[],"brief":{"pressure":[],"ripe":[],"twb":null}}';
  const settle = async (sid) => { await until(() => !env.ctx.chat.isBusy() && !env.ctx.chat.isReplaying() && queuedCount(sid) === 0 && !workIsRunning(sid), 'the replay and its readers', 60000); await tick(200); };
  try {
    const st = await db.stories.create({ title: 'a version walked on an older page' });
    await db.stories.update(st.id, { continuity: false });
    let ts = Date.now() - 600000;
    const ids = [];
    for (let i = 0; i < 4; i += 1) {
      await db.messages.append(st.id, { role: 'user', text: 'move ' + i, ts: (ts += 100) });
      const a = await db.messages.append(st.id, i === 1 ? { role: 'assistant', text: RAID, swipes: [{ text: RAID }, { text: SHRUG }], swipeIdx: 0, ts: (ts += 100) } : { role: 'assistant', text: H('09:1' + i) + 'The yard was quiet, page ' + i + '.', ts: (ts += 100) });
      ids.push(a.id);
    }
    let led = { ...emptyState(), page: 0 };
    led = applyMutations(led, [{ type: 'mc.set', name: 'Jovan' }, { type: 'place.set', name: 'The yard' }, { type: 'presence.enter', name: 'Jovan' }]).state;
    led.page = 3; led.readTo = 3;
    await saveState(st.id, led);
    const lastText = (await db.messages.list(st.id)).filter((m) => !m.hidden).slice(-1)[0].text;
    await db.settings.set(PLANS_KEY(st.id), { plans: [{ ...raid, parts: raid.parts.map((x) => ({ ...x, done: false })), status: 'standing', from: 3, to: 3, at: 1 }], readTo: 7, readHash: fingerprint36(lastText) });
    env.window.__cozy.setActiveStoryId(st.id);
    await env.ctx.chat.refreshStories(true);
    await env.ctx.chat.renderThread({ structural: true });
    await settle(st.id);
    read.length = 0;
    const walk = async (dir, want) => {
      const node = qa('#thread .msg').find((n) => n.dataset.id === ids[1]);
      assert(node, 'the older page is on the thread');
      click(q('.msg-act[data-act="' + (dir > 0 ? 'swipe-next' : 'swipe-prev') + '"]', node));
      await until(async () => (await db.messages.list(st.id)).find((m) => m.id === ids[1]).text === want, 'the version walked to', 15000);
      await until(() => env.ctx.chat.isReplaying() || queuedCount(st.id) > 0 || workIsRunning(st.id), 'the ledger rebuilt from the older page', 10000);
      await settle(st.id);
    };
    await walk(1, SHRUG);
    assert(read.some((p) => /shrugged/.test(p) && !/quiet, page/.test(p)), 'the plans keeper read the version now shown, alone — read: ' + JSON.stringify(read.map((p) => p.slice(0, 80))));
    let book = await loadPlansBook(st.id);
    eq(book.plans.filter((p) => p.status === 'standing').map((p) => p.title).join(', '), '', 'the raid the left version laid out is gone from the plans');
    eq(book.readTo, 7, 'the pages after it stay read');
    read.length = 0;
    await walk(-1, RAID);
    assert(read.some((p) => /night raid/.test(p)), 'walked back, that version is read again');
    book = await loadPlansBook(st.id);
    eq(book.plans.filter((p) => p.status === 'standing').map((p) => p.title + ' ' + p.from).join(', '), 'the night raid 3', 'and its raid is written down again, on its page');
  } finally {
    house.state.workerAnswer = prior.worker; house.state.plansAnswer = prior.plans;
    if (keeperWas === undefined) await db.settings.delete('memoryKeeper'); else await db.settings.set('memoryKeeper', keeperWas);
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-311 A PAGE FOLDED AWAY LEAVES THE STORY; BROUGHT BACK, IT COMES BACK (M681 — the books audit’s B2): the housekeeper’s “Fold this page away from the story” flipped the page’s `hidden` and nothing else — every page after it moved down one under the ledger’s stamps, the record’s lines and the plans keeper’s pages: the ledger kept the folded page’s writes, and every later rebuild kept and dropped the wrong pages’ writes. Folded away, its writes go and every later write moves down one; brought back (its fold taken back), it is read again and every later write moves up one; and a page let go moves the plans with it', async () => {
  const before = errors.length;
  const { saveState, emptyState, loadState } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const { saveMemory, loadMemory } = await import('../../js/agents/memory.js');
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  const { PLANS_KEY, loadPlansBook } = await import('../../js/agents/plans.js');
  const { fingerprint36 } = await import('../../js/engine/fingerprint.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const prior = { worker: house.state.workerAnswer, plans: house.state.plansAnswer };
  const autoWas = await db.settings.get('hkAutoApply');
  await db.settings.set('hkAutoApply', false);
  const TITLES = ['the bell tower', 'the river crossing', 'the salt debt', 'the lost ring', 'the broken oath', 'the masked envoy'];
  const SAID = ['rang the bell', 'crossed the river', 'owed the salt merchant', 'lost the ring', 'broke the oath', 'met the masked envoy'];
  const H = (i) => '[The yard — Monday, March 3, 2025 | 09:1' + i + ' | clear]\n\n';
  const plan = (title, from) => ({ title, by: 'Kim', goal: title, parts: [{ who: 'Kim', does: 'does it', when: 'then', done: false }], words: [], status: 'standing', from, to: from, at: 1 });
  let target = null;
  const readBy = [];
  const pagesPart = (body) => String(((body.messages || []).slice(-1)[0] || {}).content || '').split('The pages to read')[1] || '';
  house.state.workerAnswer = (body, sys) => {
    const user = String(((body.messages || []).slice(-1)[0] || {}).content || '');
    if (/housekeeper of a cozy tavern/i.test(sys)) return 'One fold.\n<edits>[{"id":"#' + target.slice(0, 6) + '","hide":true,"reason":"a test"}]</edits>';
    if (/keep the ledger/i.test(sys)) { const pg = newPageOf(user); const i = SAID.findIndex((w) => pg.includes(w)); if (i !== -1) readBy.push(i); return i === 2 ? JSON.stringify({ mutations: [{ type: 'thread.set', title: TITLES[2] }] }) : '{"mutations":[]}'; }
    if (/narrative-state tracker/i.test(sys)) return 'The scene turned again; the page moved on.';
    return '{"mutations":[],"deltas":[],"findings":[],"issues":[],"brief":{"pressure":[],"ripe":[],"twb":null}}';
  };
  house.state.plansAnswer = (body) => (/owed the salt merchant/.test(pagesPart(body)) ? JSON.stringify({ new: [{ title: 'the raid', by: 'Kim', goal: 'the raid', page: 6, parts: [{ who: 'Kim', does: 'does it', when: 'then' }] }], progress: [], closed: [] }) : '{"new":[],"progress":[],"closed":[]}');
  const settle = async (sid) => { await until(() => !env.ctx.chat.isBusy() && !env.ctx.chat.isReplaying() && queuedCount(sid) === 0 && !workIsRunning(sid), 'the rebuild and its readers', 60000); await tick(300); };
  const stamps = (led) => TITLES.map((t) => { const e = (led.journal || []).find((x) => x.m && x.m.type === 'thread.set' && x.m.title === t); return e ? t + '@' + e.p : t + ' gone'; }).join(', ');
  const lines = async (sid) => (await loadMemory(sid)).nodes.map((n) => n.id + ' ' + n.span.join('–')).join(' | ');
  const plans = async (sid) => { const b = await loadPlansBook(sid); return b.plans.filter((p) => p.status === 'standing').map((p) => p.title + '@' + p.from).sort().join(', ') + ' · read to ' + b.readTo + (b.again.length ? ' · owed ' + b.again.join(',') : ''); };
  try {
    const st = await db.stories.create({ title: 'a page folded away' });
    await db.stories.update(st.id, { keeper: false, continuity: false });
    let ts = Date.now() - 600000;
    const ids = [];
    for (let i = 0; i < 6; i += 1) {
      await db.messages.append(st.id, { role: 'user', text: 'move ' + i, ts: (ts += 100) });
      ids.push((await db.messages.append(st.id, { role: 'assistant', text: H(i) + 'Kim ' + SAID[i] + ' — page ' + i + '.', ts: (ts += 100) })).id);
    }
    let led = { ...emptyState(), page: 0 };
    led = applyMutations(led, [{ type: 'mc.set', name: 'Jovan' }, { type: 'place.set', name: 'The yard' }, { type: 'presence.enter', name: 'Jovan' }]).state;
    for (let p = 0; p < 6; p += 1) { led.page = p; led = applyMutations(led, [{ type: 'thread.set', title: TITLES[p] }]).state; }
    led.readTo = 5;
    await saveState(st.id, led);
    await saveMemory(st.id, { window: 4, nodes: [0, 1, 2].map((k) => ({ id: 'k' + (k + 1), span: [k * 4, k * 4 + 3], level: 1, text: 'Kim kept busy in the yard (' + k + ').', at: 1, whole: true })) });
    await db.settings.set(PLANS_KEY(st.id), { plans: [plan('the raid', 5), plan('the feast', 9), plan('the signal', 11)], readTo: 11, readHash: fingerprint36(H(5) + 'Kim ' + SAID[5] + ' — page 5.') });
    env.window.__cozy.setActiveStoryId(st.id);
    await env.ctx.chat.refreshStories(true);
    await env.ctx.chat.renderThread({ structural: true });
    await settle(st.id);
    eq(stamps(await loadState(st.id)), 'the bell tower@0, the river crossing@1, the salt debt@2, the lost ring@3, the broken oath@4, the masked envoy@5', 'fixture: every page’s write, stamped with its page');
    /* 1. the housekeeper folds page 2 away */
    target = ids[2];
    click(q('#btn-housekeeper'));
    await until(() => !q('#hk-sheet').hidden, 'the housekeeper');
    await until(() => !q('#hk-send').disabled, 'the housekeeper free to be asked', 10000);
    type(q('#hk-input'), 'fold the salt merchant page away');
    submit(q('#hk-form'));
    await until(() => qa('#hk-cards button').find((b) => /^Apply$/i.test(b.textContent.trim())), 'an Apply button', 10000);
    await until(() => !q('#hk-send').disabled, 'the answer to finish', 10000);
    await tick(200);
    click(qa('#hk-cards button').find((b) => /^Apply$/i.test(b.textContent.trim())));
    await until(async () => (await db.messages.list(st.id)).find((m) => m.id === ids[2]).hidden === true, 'the page folded away', 10000);
    await tick(300);
    await settle(st.id);
    let now = await loadState(st.id);
    eq(stamps(now), 'the bell tower@0, the river crossing@1, the salt debt gone, the lost ring@2, the broken oath@3, the masked envoy@4', 'the folded page’s write is gone, and every later write is one page down');
    assert(!(now.threads || []).some((t) => t.title === 'the salt debt'), 'the ledger no longer holds what the folded page wrote');
    eq(now.readTo, 4, 'every page that shows is read');
    eq(await lines(st.id), 'k1 0–3 | k2 4–6 | k3 7–10', 'the record slides down one (no keeper: the line over it stays over the pages it still covers)');
    eq(await plans(st.id), 'the feast@8, the signal@10 · read to 10', 'the plans keeper’s pages move down one; the folded page’s plan is gone');
    /* 2. the fold taken back: the page comes back, and is read again */
    readBy.length = 0;
    click(q('#hk-undo'));
    await until(async () => (await db.messages.list(st.id)).find((m) => m.id === ids[2]).hidden !== true, 'the page shows again', 10000);
    await until(() => readBy.includes(2), 'the page that came back is read by the ledger’s reader', 30000);
    await settle(st.id);
    now = await loadState(st.id);
    eq(stamps(now), 'the bell tower@0, the river crossing@1, the salt debt@2, the lost ring@3, the broken oath@4, the masked envoy@5', 'its write is back on its page, and every later write one page up');
    eq([...new Set(readBy)].join(','), '2', 'and no other page was read again'); /* (the reader asks once more for a mood board it was not given: the same page, twice) */
    eq(now.readTo, 5, 'every page is read');
    eq(await lines(st.id), 'k1 0–3 | k2 4–7 | k3 8–11', 'the record moves up one');
    eq(await plans(st.id), 'the feast@9, the raid@5, the signal@11 · read to 11', 'the plans keeper read the page that came back, alone, and every plan stands on its page');
    click(q('#btn-housekeeper')); await tick(300);
    /* 3. a page let go in the middle: the plans move with it (the newest page's plan was taken back, the gone page's kept) */
    const node = qa('#thread .msg').find((n) => n.dataset.id === ids[2]);
    assert(node, 'the page is on the thread');
    const priorConfirm = env.window.confirm; env.window.confirm = () => true;
    try { click(q('.msg-act[data-act="delete"]', node)); await until(async () => !(await db.messages.list(st.id)).some((m) => m.id === ids[2]), 'the page let go', 15000); } finally { env.window.confirm = priorConfirm; }
    await settle(st.id);
    eq(await plans(st.id), 'the feast@8, the signal@10 · read to 10', 'the plans keeper’s pages move down with it');
  } finally {
    house.state.workerAnswer = prior.worker; house.state.plansAnswer = prior.plans;
    if (autoWas === undefined) await db.settings.delete('hkAutoApply'); else await db.settings.set('hkAutoApply', autoWas);
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-312 “NOTHING DUE YET” IS NEVER SAID OVER A KEEPER THAT IS DOWN (M681 — the books audit’s B5): with the record keeper’s model answering nothing at all — not even a one-word question — and a record behind, the page’s keeper said “nothing due yet” on the workers’ line', async () => {
  const before = errors.length;
  const { saveState, emptyState } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const { saveMemory } = await import('../../js/agents/memory.js');
  const { loadWorkerStatus } = await import('../../js/agents/status.js');
  const { queuedCount, workIsRunning } = await import('../../js/agents/queue.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm', maxTokens: 800 });
  const prior = { worker: house.state.workerAnswer, story: house.state.storyAnswer };
  const windowWas = await db.settings.get('memoryWindow');
  await db.settings.set('memoryWindow', 20);
  const H = '[The yard — Monday, March 3, 2025 | 09:30 | clear]\n\n';
  house.state.workerAnswer = (body, sys) => (/narrative-state tracker/i.test(sys) ? '' : '{"mutations":[],"deltas":[],"findings":[],"issues":[],"brief":{"pressure":[],"ripe":[],"twb":null}}');
  house.state.storyAnswer = (body) => (/single word: ready/.test(JSON.stringify((body.messages || []).slice(-1))) ? '' : H + 'Kim waited by the wall while the yard went quiet.');
  try {
    const st = await db.stories.create({ title: 'a keeper that is down' });
    await db.stories.update(st.id, { keeper: true, continuity: false });
    let ts = Date.now() - 600000;
    for (let i = 0; i < 16; i += 1) {
      await db.messages.append(st.id, { role: 'user', text: 'on ' + i, ts: (ts += 100) });
      await db.messages.append(st.id, { role: 'assistant', text: H + 'The scene turns, page ' + i + '.', ts: (ts += 100) });
    }
    let led = { ...emptyState(), page: 0 };
    led = applyMutations(led, [{ type: 'mc.set', name: 'Jovan' }, { type: 'place.set', name: 'The yard' }, { type: 'presence.enter', name: 'Jovan' }]).state;
    led.page = 15; led.readTo = 15;
    await saveState(st.id, led);
    await saveMemory(st.id, { window: 20, nodes: [] });
    env.window.__cozy.setActiveStoryId(st.id);
    await env.ctx.chat.refreshStories(true);
    await env.ctx.chat.renderThread({ structural: true });
    await until(() => !env.ctx.chat.isBusy() && !q('.msg-pending'), 'the house free', 20000);
    const t0 = Date.now();
    type(q('#composer-input'), 'I wait by the wall.');
    submit(q('#composer'));
    /* what the page's own keeper said — read the moment it is written (the house's own gap filler may speak after it) */
    let said = null;
    await until(async () => { const k = ((await loadWorkerStatus(st.id)) || {}).keeper; if (k && Number(k.at) >= t0 && said === null && !/a gap in the record/.test(String(k.detail || ''))) said = k; return said !== null; }, 'the page’s keeper to say what it did', 60000);
    assert(!/nothing due yet/.test(String(said.detail || '')), 'the keeper does not say “nothing due yet” while it is down: ' + JSON.stringify(said));
    assert(/could not fold the record yet/.test(String(said.detail || '')) && /not answering at all/.test(String(said.detail || '')), 'it says what stopped it: ' + JSON.stringify(said.detail));
    eq(said.unfinished, true, 'and that it did not finish (the light shows it, and the house folds the gap itself when it can)');
    await until(() => !env.ctx.chat.isBusy() && queuedCount(st.id) === 0 && !workIsRunning(st.id), 'the house to settle', 60000);
  } finally {
    house.state.workerAnswer = prior.worker; house.state.storyAnswer = prior.story;
    if (windowWas === undefined) await db.settings.delete('memoryWindow'); else await db.settings.set('memoryWindow', windowWas);
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-313 HIS WORDS PUT BACK OVER A MEND ARE READ AGAIN BY THE PLANS KEEPER (M681 — B1’s pattern: every door that changes a page’s words tells it): “Put the earlier words back” on an older page left the plan as the mended words had it — the plans keeper was told nothing', async () => {
  const before = errors.length;
  const { PLANS_KEY, loadPlansBook } = await import('../../js/agents/plans.js');
  const { fingerprint36 } = await import('../../js/engine/fingerprint.js');
  const st = await db.stories.create({ title: 'his words put back' });
  await db.messages.append(st.id, { role: 'user', text: 'I listen.' });
  const a = await db.messages.append(st.id, { role: 'assistant', text: 'The raid: Kris opens the gate on the bell.' });
  await db.messages.update(st.id, a.id, { mended: { before: 'The raid: Kim opens the gate on the bell.', why: 'the second reader: a test', at: 1 } });
  await db.messages.append(st.id, { role: 'user', text: 'I nod.' });
  await db.messages.append(st.id, { role: 'assistant', text: 'They wait for the bell.' });
  await db.settings.set(PLANS_KEY(st.id), { plans: [{ title: 'the raid', by: 'Kris', goal: 'the gate', parts: [{ who: 'Kris', does: 'opens the gate', when: 'on the bell', done: false }], words: [], status: 'standing', from: 1, to: 1, at: 1 }], readTo: 3, readHash: fingerprint36('They wait for the bell.') });
  env.window.__cozy.setActiveStoryId(st.id);
  await env.ctx.chat.renderThread({ structural: true });
  await env.ctx.chat.unmend(a.id);
  eq((await db.messages.list(st.id)).find((m) => m.id === a.id).text, 'The raid: Kim opens the gate on the bell.', 'fixture: his words are back');
  const book = await loadPlansBook(st.id);
  eq(book.again.join(','), '1', 'the page is owed a second reading by the plans keeper');
  eq(book.plans.filter((p) => p.status === 'standing').length, 0, 'and the plan the mended words laid out is set aside until it is read');
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-314 A TALE OPENED WHILE THE SHELF IS BEING READ STAYS OPEN (M681 — found running down walk DOM-263, red once in a full walk): the shelf read its list of tales, waited on its other reads, and then judged the open tale against that list — a tale made and opened in between was not in it, so the shelf "put right" the open tale to the first one on it, and the next page he sent was told into another tale', async () => {
  const before = errors.length;
  const was = env.window.__cozy.getActiveStoryId();
  const a = await db.stories.create({ title: 'the tale that was open' });
  env.window.__cozy.setActiveStoryId(a.id);
  await env.ctx.chat.refreshStories(true);
  const realList = db.projects.list;
  let release = null; const gate = new Promise((r) => { release = r; });
  let reached = false;
  db.projects.list = async (...args) => { reached = true; await gate; return realList.apply(db.projects, args); };
  let b = null;
  try {
    const refresh = env.ctx.chat.refreshStories(); /* not kept: it judges the open tale when its reads are done */
    await until(() => reached, 'the shelf read its list of tales and waits on its next read');
    b = await db.stories.create({ title: 'opened while the shelf was read' });
    env.window.__cozy.setActiveStoryId(b.id);
    release();
    await refresh;
    eq(env.window.__cozy.getActiveStoryId(), b.id, 'the tale he opened is still the open tale');
  } finally {
    db.projects.list = realList;
    if (release) release();
    for (const st of [a, b]) if (st) await db.stories.remove(st.id).catch(() => {});
    env.window.__cozy.setActiveStoryId(was);
    await env.ctx.chat.refreshStories(true).catch(() => {});
  }
  eq(errorsSince(before).length, 0, errorsSince(before).join(' | '));
});

test('DOM-315 WORDS PUT BACK retire only the keeper line over that page; his own record and a disabled keeper keep their words', async () => {
  const { saveMemory, loadMemory } = await import('../../js/agents/memory.js');
  for (const kind of ['keeper', 'writer', 'off']) {
    const st = await db.stories.create({ title: 'put back with ' + kind, keeper: kind !== 'off' });
    await db.stories.update(st.id, { keeper: kind !== 'off' });
    const a = await db.messages.append(st.id, { role: 'assistant', text: 'Liara opened the east gate.', mended: { before: 'Liara opened the west gate.', why: 'test' } });
    const line = { id: 'original-line', span: [0, 0], text: 'Liara opened the east gate.', ...(kind === 'writer' ? { verified: { fixed: 'the writer' } } : {}) };
    await saveMemory(st.id, { window: 20, nodes: [line] });
    env.window.__cozy.setActiveStoryId(st.id);
    await env.ctx.chat.renderThread({ structural: true });
    await env.ctx.chat.unmend(a.id);
    const nodes = (await loadMemory(st.id)).nodes;
    eq(nodes.length, kind === 'keeper' ? 0 : 1, kind + ' record follows its own preservation rule');
    if (nodes.length) eq(nodes[0].text, line.text, 'the kept words are unchanged');
    eq((await db.messages.list(st.id))[0].text, 'Liara opened the west gate.');
  }
});

test('DOM-316 A READER IN FLIGHT writes nothing into shifted page indices between a housekeeper fold and the ledger rebase', async () => {
  const { emptyState, saveState, loadState } = await import('../../js/engine/state.js');
  const { stageProposals, applyProposal } = await import('../../js/agents/housekeeper.js');
  const { pendingWork } = await import('../../js/agents/extractor.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm' });
  const st = await db.stories.create({ title: 'a reader crossing the fold', extraction: true, keeper: false });
  const first = await db.messages.append(st.id, { role: 'assistant', text: 'They arrived in the yard.' });
  await db.messages.append(st.id, { role: 'user', text: 'I listen.' });
  const last = await db.messages.append(st.id, { role: 'assistant', text: 'FOLD_READING_PROBE Liara spoke about the tower.' });
  const ledger = emptyState(); ledger.sheet.playerName = 'Jovan'; ledger.place = { name: 'the yard' }; ledger.present = [{ name: 'Jovan' }, { name: 'Liara' }]; ledger.page = 0; ledger.readTo = 0;
  await saveState(st.id, ledger);
  env.window.__cozy.setActiveStoryId(st.id);
  await env.ctx.chat.renderThread({ structural: true });
  const prior = house.state.workerAnswer;
  let reached = false; let release; const gate = new Promise((r) => { release = r; });
  house.state.workerAnswer = async (body, sys) => {
    if (/keep the ledger/i.test(sys) && /FOLD_READING_PROBE/.test(newPageOf(body.messages.slice(-1)[0].content))) {
      reached = true; await gate;
      return JSON.stringify({ mutations: [{ type: 'mode.snapshot', flags: [] }, { type: 'knowledge.add', name: 'Liara', fact: 'The tower password is amber.' }] });
    }
    return walkDefaultWorker(body, sys);
  };
  try {
    await env.ctx.chat.pageReinked(st, last.id);
    await until(() => reached, 'the page reader held on the wire');
    const cards = stageProposals({ edits: [{ id: first.id, hide: true }], ledits: [], redits: [] }, { messages: await db.messages.list(st.id), state: await loadState(st.id), modules: [] });
    const session = { turns: [{ role: 'housekeeper', text: 'fold it', proposals: cards }], batches: [] };
    const applied = await applyProposal(session, st.id, cards[0].id);
    assert(applied.ok && applied.folded.length === 1, 'the real housekeeper folded the page');
    release();
    await pendingWork(st.id, 10000);
    const now = await loadState(st.id);
    assert(!(now.knowledge.Liara || []).some((k) => /password is amber/.test(k.fact)), 'the old reading cannot land in the gap before pageFolded');
    house.state.workerAnswer = prior;
    await env.ctx.chat.pageFolded(st, first.id);
    await settled();
  } finally { release(); house.state.workerAnswer = prior; }
});

test('DOM-317 A CUT PAGE READING keeps its useful writes but leaves the whole page owed to the reader', async () => {
  const { emptyState, saveState, loadState, readMark } = await import('../../js/engine/state.js');
  const { pendingWork } = await import('../../js/agents/extractor.js');
  if (!(await db.connections.list()).length) await db.connections.add({ name: 'mock', type: 'openai', baseUrl: 'https://mock.example/v1', apiKey: 'k', model: 'm' });
  const st = await db.stories.create({ title: 'the reader ran out of room' });
  const page = await db.messages.append(st.id, { role: 'assistant', text: 'Liara sat beside Jovan in the yard and spoke of the tower.' });
  const ledger = emptyState(); ledger.sheet.playerName = 'Jovan'; ledger.place = { name: 'the yard' }; ledger.present = [{ name: 'Jovan' }];
  await saveState(st.id, ledger);
  env.window.__cozy.setActiveStoryId(st.id);
  await env.ctx.chat.renderThread({ structural: true });
  const old = globalThis.fetch; let reads = 0;
  globalThis.fetch = async (url, opts = {}) => {
    const body = opts.body ? JSON.parse(opts.body) : {};
    const sys = (body.messages || []).filter((m) => m.role === 'system').map((m) => m.content).join('\n');
    if (!/keep the ledger/i.test(sys)) return old(url, opts);
    reads += 1;
    const answer = JSON.stringify({ mutations: [{ type: 'mode.snapshot', flags: [] }, { type: 'presence.enter', name: 'Liara' }] });
    const text = 'data: ' + JSON.stringify({ choices: [{ delta: { content: answer } }] }) + '\n\ndata: ' + JSON.stringify({ choices: [{ delta: {}, finish_reason: 'length' }] }) + '\n\ndata: [DONE]\n\n';
    return { ok: true, status: 200, headers: new Headers(), body: new ReadableStream({ start(c) { c.enqueue(new TextEncoder().encode(text)); c.close(); } }), clone() { return this; }, async json() { return {}; }, async text() { return text; } };
  };
  try {
    await env.ctx.chat.pageReinked(st, page.id);
    await pendingWork(st.id, 10000);
    const now = await loadState(st.id);
    assert(reads >= 2, 'the cut answer earned its complete second ask');
    assert(now.present.some((p) => p.name === 'Liara'), 'the useful prefix was kept');
    eq(readMark(now), -1, 'a cut reading never claims the whole page was read');
  } finally { globalThis.fetch = old; }
});

test('DOM-M683-1 resending a refused housekeeper block removes its banner and grey receipt, through the actual buttons and after reopening', async () => {
  const { loadSession } = await import('../../js/agents/housekeeper.js');
  const before = errors.length, priorAnswer = house.state.workerAnswer;
  const priorAuto = await db.settings.get('hkAutoApply');
  const priorStory = await storyId();
  let repaired = false;
  const malformed = 'A fix.\n<brief>not JSON</brief>';
  house.state.workerAnswer = (body, sys) => /housekeeper of a cozy tavern/i.test(sys)
    ? repaired ? 'The readable fix.\n<brief>[{"field":"brief","find":"twenty","replace":"nineteen","reason":"your correction"}]</brief>' : malformed
    : priorAnswer(body, sys);
  try {
    if (!q('#hk-sheet').hidden) click(q('#btn-hk-close'));
    const st = await db.stories.create({ title: 'M683 resend' });
    await db.stories.update(st.id, { brief: 'Alexia is twenty.', keeper: false, continuity: false });
    await db.settings.set('hkAutoApply', false);
    env.window.__cozy.setActiveStoryId(st.id);
    await env.ctx.chat.refreshStories(true);
    await env.ctx.chat.renderThread({ structural: true });
    click(q('#btn-housekeeper'));
    await until(() => !q('#hk-sheet').hidden && !q('#hk-send').disabled, 'housekeeper ready', 10000);
    type(q('#hk-input'), 'Alexia is nineteen. Correct the brief.'); submit(q('#hk-form'));
    await until(() => !q('#hk-send').disabled && qa('#hk-cards .hk-refused').length > 0, 'a refused unreadable card', 10000);
    assert(!q('#hk-repropose').hidden, 'the real resend control offers the failed block');
    repaired = true; click(q('#hk-repropose'));
    await until(() => !q('#hk-send').disabled && qa('#hk-cards .hk-pending').length === 1, 'the readable correction', 10000);
    eq(qa('#hk-cards .hk-refused').length, 0, 'the failed banner disappears');
    assert(q('#hk-repropose').hidden, 'no failed proposal remains to resend');
    assert(!qa('#hk-thread .hk-receipt').some((n) => /superseded|could not read/i.test(n.textContent)), 'no grey obsolete warning in the conversation');
    const saved = await loadSession(st.id);
    const old = saved.turns.find((t) => t.raw === malformed);
    assert(old && old.proposals.every((p) => p.status === 'superseded'), 'old failure is retired and raw answer retained');
    click(qa('#hk-cards button').find((b) => /^Apply$/i.test(b.textContent.trim())));
    await until(async () => (await db.stories.get(st.id)).brief === 'Alexia is nineteen.' && q('#hk-cards').hidden, 'applied correction and no banner', 10000);
    click(q('#btn-hk-close')); click(q('#btn-housekeeper'));
    await until(() => !q('#hk-sheet').hidden && !q('#hk-send').disabled, 'reopened', 10000);
    assert(q('#hk-cards').hidden, 'obsolete notices stay gone after reopening');
    assert(!qa('#hk-thread .hk-receipt').some((n) => /superseded|could not read/i.test(n.textContent)), 'obsolete receipt stays gone');
    eq(errors.length, before, 'no app errors');
  } finally {
    house.state.workerAnswer = priorAnswer;
    if (!q('#hk-sheet').hidden) click(q('#btn-hk-close'));
    if (priorAuto === undefined) await db.settings.delete('hkAutoApply'); else await db.settings.set('hkAutoApply', priorAuto);
    env.window.__cozy.setActiveStoryId(priorStory);
    await env.ctx.chat.refreshStories(true); await env.ctx.chat.renderThread({ structural: true });
  }
});

test('DOM-M684-1 introductions survive the full reader chain, a world cut, the drawer and reopening', async () => {
  const { emptyState, saveState, loadState } = await import('../../js/engine/state.js');
  const { applyMutations } = await import('../../js/engine/apply.js');
  const { pendingWork } = await import('../../js/agents/extractor.js');
  const previous = house.state.workerAnswer, priorStory = await storyId(), errorAt = errors.length;
  const alexia = 'Princess Alexia is the Second Princess and stands beside me in the salon.';
  const caelan = 'Prince Caelan is the Third Prince and lives at the northern estate.';
  const input = alexia + ' ' + caelan + ' I offer her a chair.';
  house.state.workerAnswer = (body, sys) => {
    if (/keep the ledger/i.test(sys)) return JSON.stringify({ mutations: [{ type: 'mode.snapshot', flags: ['group'] }], people: [{ name: 'Princess Alexia', shown: alexia }, { name: 'Prince Caelan', shown: caelan }], here: ['Jovan', 'Princess Alexia'] });
    if (/world beyond the page/i.test(sys)) return JSON.stringify({ mutations: [{ type: 'offscreen.set', name: 'Prince Caelan', location: 'the northern estate', activity: 'meeting his steward', cause: 'He remains at his established estate while the salon conversation continues.' }], brief: { pressure: [], ripe: [], twb: null } });
    if (/character pages/i.test(sys)) return '{"deltas":[]}';
    if (/auditor of the ledger/i.test(sys)) return '{"issues":[]}';
    return previous(body, sys);
  };
  try {
    const st = await db.stories.create({ title: 'M684 introductions' });
    await db.stories.update(st.id, { keeper: false, continuity: false, extraction: true, world: true });
    const story = await db.stories.get(st.id);
    await db.messages.append(st.id, { role: 'user', text: input });
    const page = await db.messages.append(st.id, { role: 'assistant', text: '[the palace salon — Monday | 10:00]\n\nShe takes the offered chair and smiles.\n\n*** The World Beyond ***\n[the market]\nNella purchases a loaf of bread.' });
    await saveState(st.id, applyMutations({ ...emptyState(), page: 0 }, [{ type: 'mc.set', name: 'Jovan' }, { type: 'place.set', name: 'the palace salon' }, { type: 'presence.enter', name: 'Jovan' }]).state);
    env.window.__cozy.setActiveStoryId(st.id);
    await env.ctx.chat.refreshStories(true); await env.ctx.chat.renderThread({ structural: true });
    await env.ctx.chat.pageReinked(story, page.id);
    await pendingWork(st.id, 10000);
    const now = await loadState(st.id);
    assert(now.present.some((p) => p.name === 'Princess Alexia'), 'the full chain retains the writer’s nearby princess');
    assert(!now.present.some((p) => /Caelan|Nella/.test(p.name)), 'absent and world-window people remain outside the room');
    assert(now.characters['Princess Alexia']?.core.includes('Second Princess'), 'her exact rank reaches People');
    assert(now.characters['Prince Caelan']?.core.includes('Third Prince'), 'the absent prince gets a page too');
    eq(now.offscreen['Prince Caelan']?.location, 'the northern estate', 'the world seats the introduced absent person');
    if (!q('#drawer').hidden) { click(q('#btn-drawer-close')); await until(() => q('#drawer').hidden, 'closed old drawer'); }
    click(q('#btn-ledger')); await until(() => !q('#drawer').hidden, 'ledger opens');
    await env.ctx.drawer.renderAllRooms(); await tick(450);
    assert(q('#drawer [data-panel="whos-here"]')?.textContent.includes('Princess Alexia') || q('#drawer .present-editor')?.textContent.includes('Princess Alexia'), 'the actual scene list names her');
    const changes = q('#drawer [data-panel="what-changed"]');
    assert(changes?.textContent.includes('Your input') && changes.textContent.includes('Source:') && changes.textContent.includes('Second Princess'), 'Books explains the source of the introduction');
    assert(q('#drawer [data-panel="something-drifted"]')?.textContent.includes('No correction or unresolved issue') || q('#drawer [data-panel="something-drifted"]')?.textContent.includes('found no ledger issue'), 'audit results are stated without a blanket all-clear');
    click(q('#btn-drawer-close'));
    env.window.__cozy.setActiveStoryId(priorStory); await env.ctx.chat.renderThread({ structural: true });
    env.window.__cozy.setActiveStoryId(st.id); await env.ctx.chat.renderThread({ structural: true });
    await pendingWork(st.id, 10000);
    assert((await loadState(st.id)).present.some((p) => p.name === 'Princess Alexia'), 'opening heals do not undo a valid introduction');
    eq(errors.length, errorAt, 'no app errors');
  } finally {
    house.state.workerAnswer = previous;
    if (!q('#drawer').hidden) click(q('#btn-drawer-close'));
    env.window.__cozy.setActiveStoryId(priorStory);
    await env.ctx.chat.refreshStories(true); await env.ctx.chat.renderThread({ structural: true });
  }
});

